INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-04faa606db3d','CAT4','verbal','mcq',4,NULL,'Which pair has the same relationship as "pebble : boulder"?',NULL,'["puddle : lake","tree : leaf","road : car","cloud : rain"]',0,'A pebble is a small stone and a boulder a large one; a puddle is small water and a lake large water.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-3e68b757c11b','CAT4','verbal','mcq',4,NULL,'All roses are flowers. Some flowers are red. Which MUST be true?',NULL,'["All roses are red.","Some roses are red.","No roses are red.","None of these must be true."]',3,'Nothing says the red flowers are roses, so none of the statements must be true.',1,0);
