INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-681e02639ee4','MAP','reading','mcq',3,'When the town planted trees along Maple Street, many residents complained about the cost. Ten years later, the shade lowered summer temperatures by several degrees, and neighbours began gathering under the branches each evening. The mayor admitted that the trees had paid for themselves in ways no budget could measure.','What is the mayor''s attitude toward the trees by the end of the passage?',NULL,'["Regretful","Appreciative","Confused","Angry"]',1,'He admits they paid for themselves.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-5079de0a35c8','MAP','reading','mcq',4,'When the town planted trees along Maple Street, many residents complained about the cost. Ten years later, the shade lowered summer temperatures by several degrees, and neighbours began gathering under the branches each evening. The mayor admitted that the trees had paid for themselves in ways no budget could measure.','Which sentence best states a theme of the passage?',NULL,'["Costs should never be questioned.","Some investments bring benefits that are hard to measure.","Trees grow slowly.","Neighbours dislike change."]',1,'Benefits beyond budget.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-02cb0a050b7c','MAP','reading','mcq',2,'When the town planted trees along Maple Street, many residents complained about the cost. Ten years later, the shade lowered summer temperatures by several degrees, and neighbours began gathering under the branches each evening. The mayor admitted that the trees had paid for themselves in ways no budget could measure.','According to the passage, what happened ten years later?',NULL,'["The trees were cut down","Summers became cooler and neighbours gathered","The street was closed","The mayor resigned"]',1,'Stated directly.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-d307d3684084','MAP','reading','mcq',4,'Scientists studying coral reefs have noticed that reefs near busy harbours often recover more slowly after storms. The researchers suspect that pollution weakens the coral, but they caution that more data is needed before the cause can be confirmed.','Which word best describes the researchers'' conclusion?',NULL,'["Certain","Tentative","Careless","Hostile"]',1,'"Suspect" and "more data is needed" signal caution.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-a6dac2024418','MAP','reading','mcq',5,'Scientists studying coral reefs have noticed that reefs near busy harbours often recover more slowly after storms. The researchers suspect that pollution weakens the coral, but they caution that more data is needed before the cause can be confirmed.','What does "caution" mean as used in the passage?',NULL,'["to hurry","to warn","to celebrate","to ignore"]',1,'To caution = to warn.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-9fd26cf2f4b4','MAP','reading','mcq',3,'Scientists studying coral reefs have noticed that reefs near busy harbours often recover more slowly after storms. The researchers suspect that pollution weakens the coral, but they caution that more data is needed before the cause can be confirmed.','What is the passage mainly about?',NULL,'["How storms form","A possible link between harbours and slow reef recovery","Why harbours are busy","How to build harbours"]',1,'Main idea.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-1ecb99f77229','MAP','reading','mcq',5,NULL,'Choose the best meaning of "meticulous".',NULL,'["careless","extremely careful about details","quick","noisy"]',1,'Meticulous = very careful and precise.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-54f1e9150dc5','MAP','reading','mcq',3,NULL,'Which word is closest in meaning to "abundant"?',NULL,'["plentiful","empty","fragile","ordinary"]',0,'Abundant = plentiful.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-5f86c519bb6d','MAP','reading','mcq',4,NULL,'"The wind whispered through the trees." This sentence is an example of',NULL,'["simile","personification","exaggeration","rhyme"]',1,'The wind is given a human action.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-b5522fc6cae8','MAP','language','mcq',1,NULL,'Choose the correct word: "They ___ going to the zoo."',NULL,'["is","am","are","be"]',2,'"They" takes "are".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-334a0f11b854','MAP','language','mcq',1,NULL,'Which sentence begins with a capital letter and ends correctly?',NULL,'["we like pizza.","We like pizza.","We like pizza","we Like pizza?"]',1,'Capital + period.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-c39cd62781b7','MAP','language','mcq',2,NULL,'Choose the correct plural: one child, two ___',NULL,'["childs","childes","children","childrens"]',2,'Irregular plural.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-8753e4385ee4','MAP','language','mcq',2,NULL,'Which word completes the sentence? "She ran ___ than her brother."',NULL,'["fast","faster","fastest","more fast"]',1,'Comparative of two.',1,0);
