INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-4e63ff65c4ba','MAP','language','mcq',4,NULL,'Which sentence contains a misplaced modifier?',NULL,'["She nearly drove her kids to school every day.","She drove her kids to school every day.","Every day, she drove her kids to school.","She drove her kids to school daily."]',0,'"Nearly" should modify "every day" or be placed differently.',1,0);
