INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-e68de7eb15a7','CAT4','verbal','mcq',1,NULL,'Day is to night as summer is to ___',NULL,'["sun","winter","hot","season"]',1,'Day and night are opposites; so are summer and winter.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-ddb551318d63','CAT4','verbal','mcq',1,NULL,'Which word does NOT belong? dog, cat, horse, chair',NULL,'["dog","cat","horse","chair"]',3,'Dog, cat and horse are animals; a chair is furniture.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-270ce7ce2ba1','CAT4','verbal','mcq',2,NULL,'Eye is to see as ear is to ___',NULL,'["hear","sound","head","listen to"]',0,'The eye is used to see; the ear is used to hear.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-fc1f47035d61','CAT4','verbal','mcq',2,NULL,'Which word means the same as "huge"?',NULL,'["tiny","enormous","quiet","quick"]',1,'"Huge" and "enormous" both mean very large.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-d4313a861615','CAT4','verbal','mcq',3,NULL,'Chapter is to book as scene is to ___',NULL,'["actor","play","stage","ticket"]',1,'A chapter is a part of a book; a scene is a part of a play.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-634a4f8dff4b','CAT4','verbal','mcq',3,NULL,'Which word is the OPPOSITE of "generous"?',NULL,'["kind","selfish","wealthy","shy"]',1,'"Generous" means giving; the opposite is selfish.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-ec72c3192d1c','CAT4','verbal','mcq',3,NULL,'Which word does NOT belong? triangle, square, circle, cube',NULL,'["triangle","square","circle","cube"]',3,'Triangle, square and circle are flat (2-D); a cube is solid (3-D).',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-26ce4860f53e','CAT4','verbal','mcq',4,NULL,'Thermometer is to temperature as ruler is to ___',NULL,'["length","paper","wood","draw"]',0,'A thermometer measures temperature; a ruler measures length.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-ad2881a3f3e9','CAT4','verbal','mcq',4,NULL,'All birds have feathers. A penguin is a bird. Which MUST be true?',NULL,'["A penguin has feathers.","A penguin can fly.","All feathered animals are birds.","Penguins live in cold places only."]',0,'Penguins are birds and all birds have feathers, so penguins have feathers.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-70a049b3f0d4','CAT4','verbal','mcq',5,NULL,'Which word is closest in meaning to "ambiguous"?',NULL,'["clear","unclear","loud","rude"]',1,'"Ambiguous" means open to more than one meaning, i.e. unclear.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-ba5ecfedccec','CAT4','verbal','mcq',5,NULL,'Prudent is to reckless as frugal is to ___',NULL,'["thrifty","wasteful","poor","careful"]',1,'"Prudent" is the opposite of "reckless"; "frugal" is the opposite of "wasteful".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-922bb3e5d341','WIDA','listening','mcq',1,'Anna says: "My birthday is on Saturday. I''m having a party at my house."','Where is Anna''s party?',NULL,'["At school","At her house","At the park","At a restaurant"]',1,'Key line: "I''m having a party at my house." So the answer is "At her house".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-9813d27e75bd','WIDA','listening','mcq',2,'Teacher: "Tomorrow is picture day. Please wear your school shirt and bring your homework."','What should students wear tomorrow?',NULL,'["A costume","Their school shirt","A jacket","Sports clothes"]',1,'Key line: "Please wear your school shirt and bring your homework." So the answer is "Their school shirt".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-9ec21c938a43','WIDA','listening','mcq',2,'Dad: "We''re out of milk, so I''m going to the store. Do you need anything?"','Why is Dad going to the store?',NULL,'["To buy milk","To meet a friend","To return a book","To get gas"]',0,'Key line: "Dad: "We''re out of milk, so I''m going to the store." So the answer is "To buy milk".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-47489ed1d8c3','WIDA','listening','mcq',3,'Principal: "The assembly will begin at ten, but students from Room 4 should arrive early to help set up chairs."','Who should come early?',NULL,'["All students","Teachers only","Students from Room 4","Parents"]',2,'Key line: "Principal: "The assembly will begin at ten, but students from Room 4 should arrive early to help set up chairs." So the answer is "Students from Room 4".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-57a70a9f46be','WIDA','listening','mcq',4,'Ranger: "Because the trail is muddy after the rain, we will take the lower path, which is longer but safer."','Why will the group take the lower path?',NULL,'["It is shorter","It is safer","It has a view","It is closed"]',1,'Key line: "Ranger: "Because the trail is muddy after the rain, we will take the lower path, which is longer but safer." So the answer is "It is safer".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-listening-5841ebed4d80','WIDA','listening','mcq',5,'Lecturer: "Although electric cars produce no exhaust, their overall environmental benefit depends on how the electricity is generated."','What does the lecturer suggest?',NULL,'["Electric cars are always clean","Benefits depend on the electricity source","Exhaust is harmless","Electric cars are expensive"]',1,'Key line: "Lecturer: "Although electric cars produce no exhaust, their overall environmental benefit depends on how the electricity is generated." So the answer is "Benefits depend on the electricity source".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-fa9f1c35cb67','WIDA','reading','mcq',1,'Mia has a cat named Pepper. Pepper likes to sleep on the sofa and drink milk.','What does Pepper like to drink?',NULL,'["Water","Milk","Juice","Tea"]',1,'Key line: "Pepper likes to sleep on the sofa and drink milk." So the answer is "Milk".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-f5574f040ac9','WIDA','reading','mcq',2,'On Monday, the class started a garden. They planted beans, carrots, and corn. Each student has a job.','What did the class start on Monday?',NULL,'["A garden","A game","A play","A trip"]',0,'Key line: "On Monday, the class started a garden." So the answer is "A garden".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-5593a2e6571a','WIDA','reading','mcq',3,'The library offers free programs during the summer. Children can join a reading club, and older students can volunteer as helpers.','Who can volunteer as helpers?',NULL,'["Younger children","Older students","Teachers only","Nobody"]',1,'Key line: "Children can join a reading club, and older students can volunteer as helpers." So the answer is "Older students".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-c865deba078f','WIDA','reading','mcq',3,'Rain forests are home to millions of species. Many of these plants and animals cannot live anywhere else on Earth.','Why are rain forests important?',NULL,'["They are cold","They shelter species found nowhere else","They have no animals","They are small"]',1,'Key line: "Rain forests are home to millions of species." So the answer is "They shelter species found nowhere else".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-b2aac4488dab','WIDA','reading','mcq',4,'The inventor tested hundreds of materials before finding one strong enough. "Every failure," she said, "taught me what not to do."','What does the inventor''s statement show?',NULL,'["She gave up easily","She learned from failures","She disliked testing","She worked alone"]',1,'Key line: "Every failure," So the answer is "She learned from failures".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-fd7597924a01','WIDA','reading','mcq',5,'Economists note that when a product becomes scarce, its price typically rises unless demand falls at the same time.','What usually happens to the price of a scarce product?',NULL,'["It falls","It rises","It stays the same","It disappears"]',1,'Key line: "Economists note that when a product becomes scarce, its price typically rises unless demand falls at the same time." So the answer is "It rises".',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-writing-3','WIDA','writing','text',3,NULL,'Describe what you do on a typical weekend. Use at least five sentences and words like "first", "then", and "finally".',NULL,NULL,NULL,NULL,1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-speaking-3','WIDA','speaking','audio',3,NULL,'Talk about your favorite food. What is it, how is it made, and why do you like it? (Record for about 45 seconds.)',NULL,NULL,NULL,NULL,1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-math-a7f79a24f365','MAP','math','mcq',2,NULL,'Which category has exactly 15?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" width="340" height="230" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><text x="170" y="18" text-anchor="middle" font-weight="700" font-size="13">Students in each club</text><line x1="46" y1="188" x2="328" y2="188" stroke="#e5e7eb"/><text x="40" y="192" text-anchor="end" font-size="10">0</text><line x1="46" y1="172.6" x2="328" y2="172.6" stroke="#e5e7eb"/><text x="40" y="176.6" text-anchor="end" font-size="10">5</text><line x1="46" y1="157.2" x2="328" y2="157.2" stroke="#e5e7eb"/><text x="40" y="161.2" text-anchor="end" font-size="10">10</text><line x1="46" y1="141.8" x2="328" y2="141.8" stroke="#e5e7eb"/><text x="40" y="145.8" text-anchor="end" font-size="10">15</text><line x1="46" y1="126.4" x2="328" y2="126.4" stroke="#e5e7eb"/><text x="40" y="130.4" text-anchor="end" font-size="10">20</text><line x1="46" y1="111" x2="328" y2="111" stroke="#e5e7eb"/><text x="40" y="115" text-anchor="end" font-size="10">25</text><line x1="46" y1="95.6" x2="328" y2="95.6" stroke="#e5e7eb"/><text x="40" y="99.6" text-anchor="end" font-size="10">30</text><line x1="46" y1="80.2" x2="328" y2="80.2" stroke="#e5e7eb"/><text x="40" y="84.2" text-anchor="end" font-size="10">35</text><line x1="46" y1="64.8" x2="328" y2="64.8" stroke="#e5e7eb"/><text x="40" y="68.8" text-anchor="end" font-size="10">40</text><line x1="46" y1="49.400000000000006" x2="328" y2="49.400000000000006" stroke="#e5e7eb"/><text x="40" y="53.400000000000006" text-anchor="end" font-size="10">45</text><line x1="46" y1="34" x2="328" y2="34" stroke="#e5e7eb"/><text x="40" y="38" text-anchor="end" font-size="10">50</text><line x1="46" y1="34" x2="46" y2="188" stroke="#1f2937"/><line x1="46" y1="188" x2="328" y2="188" stroke="#1f2937"/><text x="12" y="111" text-anchor="middle" font-size="10" transform="rotate(-90 12 111)">Count</text><rect x="57.28" y="111" width="33.839999999999996" height="77" fill="#059669" rx="2"/><text x="74.2" y="203" text-anchor="middle" font-size="11">Soccer</text><rect x="113.68" y="141.8" width="33.839999999999996" height="46.2" fill="#059669" rx="2"/><text x="130.6" y="203" text-anchor="middle" font-size="11">Chess</text><rect x="170.08" y="80.2" width="33.839999999999996" height="107.8" fill="#059669" rx="2"/><text x="187" y="203" text-anchor="middle" font-size="11">Art</text><rect x="226.48" y="157.2" width="33.839999999999996" height="30.8" fill="#059669" rx="2"/><text x="243.39999999999998" y="203" text-anchor="middle" font-size="11">Music</text><rect x="282.88" y="95.6" width="33.839999999999996" height="92.4" fill="#059669" rx="2"/><text x="299.8" y="203" text-anchor="middle" font-size="11">Drama</text></svg>','["Chess","Art","Music","Soccer"]',0,'Only "Chess" reaches 15.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-math-6ff407c4fe87','MAP','math','mcq',4,NULL,'Between which two consecutive months did the temperature increase the most?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" width="340" height="230" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><text x="170" y="18" text-anchor="middle" font-weight="700" font-size="13">Average temperature (°C)</text><line x1="46" y1="188" x2="324" y2="188" stroke="#e5e7eb"/><text x="40" y="192" text-anchor="end" font-size="10">0</text><line x1="46" y1="168.75" x2="324" y2="168.75" stroke="#e5e7eb"/><text x="40" y="172.75" text-anchor="end" font-size="10">5</text><line x1="46" y1="149.5" x2="324" y2="149.5" stroke="#e5e7eb"/><text x="40" y="153.5" text-anchor="end" font-size="10">10</text><line x1="46" y1="130.25" x2="324" y2="130.25" stroke="#e5e7eb"/><text x="40" y="134.25" text-anchor="end" font-size="10">15</text><line x1="46" y1="111" x2="324" y2="111" stroke="#e5e7eb"/><text x="40" y="115" text-anchor="end" font-size="10">20</text><line x1="46" y1="91.75" x2="324" y2="91.75" stroke="#e5e7eb"/><text x="40" y="95.75" text-anchor="end" font-size="10">25</text><line x1="46" y1="72.5" x2="324" y2="72.5" stroke="#e5e7eb"/><text x="40" y="76.5" text-anchor="end" font-size="10">30</text><line x1="46" y1="53.25" x2="324" y2="53.25" stroke="#e5e7eb"/><text x="40" y="57.25" text-anchor="end" font-size="10">35</text><line x1="46" y1="34" x2="324" y2="34" stroke="#e5e7eb"/><text x="40" y="38" text-anchor="end" font-size="10">40</text><line x1="46" y1="34" x2="46" y2="188" stroke="#1f2937"/><line x1="46" y1="188" x2="324" y2="188" stroke="#1f2937"/><text x="12" y="111" text-anchor="middle" font-size="10" transform="rotate(-90 12 111)">°C</text><polyline fill="none" stroke="#059669" stroke-width="2.5" points="58,111 108.8,168.75 159.6,111 210.4,111 261.2,149.5 312,111"/><circle cx="58" cy="111" r="4" fill="#059669"/><text x="58" y="203" text-anchor="middle" font-size="11">Jan</text><circle cx="108.8" cy="168.75" r="4" fill="#059669"/><text x="108.8" y="203" text-anchor="middle" font-size="11">Feb</text><circle cx="159.6" cy="111" r="4" fill="#059669"/><text x="159.6" y="203" text-anchor="middle" font-size="11">Mar</text><circle cx="210.4" cy="111" r="4" fill="#059669"/><text x="210.4" y="203" text-anchor="middle" font-size="11">Apr</text><circle cx="261.2" cy="149.5" r="4" fill="#059669"/><text x="261.2" y="203" text-anchor="middle" font-size="11">May</text><circle cx="312" cy="111" r="4" fill="#059669"/><text x="312" y="203" text-anchor="middle" font-size="11">Jun</text></svg>','["Jan–Feb","Apr–May","Feb–Mar","Mar–Apr"]',2,'The largest rise is 15°C, from Feb to Mar.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-math-9bdfb1c08352','MAP','math','mcq',4,NULL,'400 students were surveyed. How many students chose "Soup"?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" width="340" height="230" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><text x="170" y="18" text-anchor="middle" font-weight="700" font-size="13">Survey results</text><path d="M110 130 L110.0 52.0 A78 78 0 0 1 184.2 154.1 Z" fill="#059669" stroke="#fff" stroke-width="2"/><text x="149.1" y="105.6" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">30%</text><rect x="215" y="58" width="12" height="12" rx="3" fill="#059669"/><text x="234" y="69" font-size="12">Pizza</text><path d="M110 130 L184.2 154.1 A78 78 0 0 1 46.9 175.8 Z" fill="#0ea5e9" stroke="#fff" stroke-width="2"/><text x="117.6" y="181.8" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">35%</text><rect x="215" y="82" width="12" height="12" rx="3" fill="#0ea5e9"/><text x="234" y="93" font-size="12">Pasta</text><path d="M110 130 L46.9 175.8 A78 78 0 0 1 35.8 105.9 Z" fill="#10b981" stroke="#fff" stroke-width="2"/><text x="62.2" y="141.6" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">15%</text><rect x="215" y="106" width="12" height="12" rx="3" fill="#10b981"/><text x="234" y="117" font-size="12">Salad</text><path d="M110 130 L35.8 105.9 A78 78 0 0 1 110.0 52.0 Z" fill="#f59e0b" stroke="#fff" stroke-width="2"/><text x="81.6" y="94.9" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">20%</text><rect x="215" y="130" width="12" height="12" rx="3" fill="#f59e0b"/><text x="234" y="141" font-size="12">Soup</text></svg>','["80","70","20","90"]',0,'20% of 400 = 80.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-math-f1f9ff175f36','MAP','math','mcq',2,NULL,'What is the area of the rectangle, in square centimeters?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 160" width="260" height="160" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><rect x="79.375" y="35" width="101.25" height="90" fill="#e0e7ff" stroke="#1f2937" stroke-width="2"/><text x="130" y="29" text-anchor="middle">9 cm</text><text x="188.625" y="84" >8 cm</text></svg>','["34","81","72","17"]',2,'Area = 9 × 8.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-math-7a3007b07780','MAP','math','mcq',4,NULL,'In the right triangle shown, what is the length of the hypotenuse (the side marked ?)','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 190" width="260" height="190" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><polygon points="50,150 196.66666666666666,150 50,40" fill="#dcfce7" stroke="#1f2937" stroke-width="2"/><path d="M50 136 h14 v14" fill="none" stroke="#1f2937"/><text x="42" y="95" text-anchor="end">9</text><text x="123.33333333333333" y="168" text-anchor="middle">12</text><text x="131.33333333333331" y="91" font-weight="700">?</text></svg>','["14","16","15","21"]',2,'9² + 12² = 15², so the hypotenuse is 15.',1,0);
