INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-70cb28efb5c7','ISEE','math','mcq',1,NULL,'What is 3/5 of 20?',NULL,'["9","15","17","12"]',3,'20 ÷ 5 × 3.',1,0);
