INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-0476b3e08443','SSAT','quantitative','mcq',3,NULL,'The average of four numbers is 12. Three of the numbers are 11, 8, and 14. What is the fourth number?',NULL,'["13","15","19","12"]',1,'Total = 4 × 12 = 48; subtract 33.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-9bd36a79417e','SSAT','quantitative','mcq',4,NULL,'The ratio of boys to girls in a class is 2:3. If there are 10 boys, how many girls are there?',NULL,'["15","17","8","13"]',0,'10 ÷ 2 = 5 groups, and 5 × 3 = 15.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-66f40cafca6d','SSAT','quantitative','mcq',2,NULL,'What is the value of √121 + 4²?',NULL,'["137","27","19","125"]',1,'√121 = 11 and 4² = 16.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-3e4d4310daa4','SSAT','quantitative','mcq',3,NULL,'If 5x − 9 = 26, what is the value of x?',NULL,'["8","7","6","12"]',1,'Add 9, divide by 5.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-ff1cf305c480','SSAT','quantitative','mcq',4,NULL,'What is 4/5 of 20?',NULL,'["21","16","5","20"]',1,'20 ÷ 5 × 4.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-645f8e54f1fa','SSAT','quantitative','mcq',2,NULL,'A jacket that costs $80 is on sale for 10% off. What is the sale price?',NULL,'["$72","$82","$70","$8"]',0,'10% of 80 = 8, so 80 − 8 = 72.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-ea3212d850d2','SSAT','quantitative','mcq',3,NULL,'A car travels at 40 miles per hour for 3 hours. How many miles does it travel?',NULL,'["43","13.3","120","130"]',2,'Distance = rate × time = 40 × 3.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-e41877eb5335','SSAT','quantitative','mcq',4,NULL,'What is 1/4 of 32?',NULL,'["4","12","25","8"]',3,'32 ÷ 4 × 1.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-0a91d0bc03a6','SSAT','quantitative','mcq',2,NULL,'The sum of three consecutive integers is 48. What is the greatest of the three integers?',NULL,'["16","18","17","15"]',2,'The middle integer is 16, so the greatest is 17.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-2d56a1392132','SSAT','quantitative','mcq',3,NULL,'The average of four numbers is 14. Three of the numbers are 11, 14, and 11. What is the fourth number?',NULL,'["14","24","20","18"]',2,'Total = 4 × 14 = 56; subtract 36.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-089aa2799e8e','SSAT','quantitative','mcq',4,NULL,'A jacket that costs $200 is on sale for 50% off. What is the sale price?',NULL,'["$110","$150","$95","$100"]',3,'50% of 200 = 100, so 200 − 100 = 100.',1,0);
