INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-c6a503082f61','SSAT','quantitative','mcq',4,NULL,'Between which two consecutive months did the temperature increase the most?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" width="340" height="230" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><text x="170" y="18" text-anchor="middle" font-weight="700" font-size="13">Average temperature (°C)</text><line x1="46" y1="188" x2="324" y2="188" stroke="#e5e7eb"/><text x="40" y="192" text-anchor="end" font-size="10">0</text><line x1="46" y1="168.75" x2="324" y2="168.75" stroke="#e5e7eb"/><text x="40" y="172.75" text-anchor="end" font-size="10">5</text><line x1="46" y1="149.5" x2="324" y2="149.5" stroke="#e5e7eb"/><text x="40" y="153.5" text-anchor="end" font-size="10">10</text><line x1="46" y1="130.25" x2="324" y2="130.25" stroke="#e5e7eb"/><text x="40" y="134.25" text-anchor="end" font-size="10">15</text><line x1="46" y1="111" x2="324" y2="111" stroke="#e5e7eb"/><text x="40" y="115" text-anchor="end" font-size="10">20</text><line x1="46" y1="91.75" x2="324" y2="91.75" stroke="#e5e7eb"/><text x="40" y="95.75" text-anchor="end" font-size="10">25</text><line x1="46" y1="72.5" x2="324" y2="72.5" stroke="#e5e7eb"/><text x="40" y="76.5" text-anchor="end" font-size="10">30</text><line x1="46" y1="53.25" x2="324" y2="53.25" stroke="#e5e7eb"/><text x="40" y="57.25" text-anchor="end" font-size="10">35</text><line x1="46" y1="34" x2="324" y2="34" stroke="#e5e7eb"/><text x="40" y="38" text-anchor="end" font-size="10">40</text><line x1="46" y1="34" x2="46" y2="188" stroke="#1f2937"/><line x1="46" y1="188" x2="324" y2="188" stroke="#1f2937"/><text x="12" y="111" text-anchor="middle" font-size="10" transform="rotate(-90 12 111)">°C</text><polyline fill="none" stroke="#059669" stroke-width="2.5" points="58,91.75 108.8,168.75 159.