INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-706d2f8add33','ISEE','math','mcq',3,NULL,'The average of four numbers is 14. Three of the numbers are 12, 14, and 14. What is the fourth number?',NULL,'["14","16","20","56"]',1,'Total = 4 × 14 = 56; subtract 40.',1,0);
