INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-2a4a337abc74','SAT','math','mcq',1,NULL,'If 9x + 19 = 136, what is the value of x?',NULL,'["12","22","14","13"]',3,'Subtract 19, divide by 9.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-43d457954994','SAT','math','mcq',2,NULL,'The function f is defined by f(x) = 2x − 11. What is f(6)?',NULL,'["1","-10","-3","23"]',0,'2(6) − 11.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-4be95712c1d6','SAT','math','mcq',2,NULL,'x + y = 6 and x − y = 4. What is the value of x?',NULL,'["5","6","1","4"]',0,'Add the two equations: 2x = 10.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-6ed618dbe8f8','SAT','math','mcq',3,NULL,'A price increased from $120 to $180. By what percent did the price increase?',NULL,'["45%","50%","55%","33%"]',1,'(180 − 120) ÷ 120 = 0.5.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-147b9171f17c','SAT','math','mcq',2,NULL,'A mixture contains red paint and blue paint in the ratio 5 : 2. If it contains 40 liters of red paint, how many liters of blue paint does it contain?',NULL,'["21","10","16","42"]',2,'40/5 = 8; 8 × 2.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-09fdd156d974','SAT','math','mcq',4,NULL,'What are the solutions to x² − 12x + 32 = 0?',NULL,'["4 and -8","-4 and -8","5 and 7","4 and 8"]',3,'(x − 4)(x − 8) = 0.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-91841f20d6ca','SAT','math','mcq',2,NULL,'If 5^x = 3125, what is the value of x?',NULL,'["4","6","25","5"]',3,'5^5 = 3125.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-7fae374c7462','SAT','math','mcq',3,NULL,'A line passes through the points (0, -3) and (1, 2). What is the slope of the line?',NULL,'["1/5","-5","5","6"]',2,'Rise over run = 5/1.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-940eab3fb869','SAT','math','mcq',2,NULL,'The mean of the five numbers 4, 17, 18, 27, 29 is 19. (Assume the mean is exactly 19.) What is the sum of the five numbers?',NULL,'["95","24","76","100"]',0,'Sum = mean × count = 19 × 5.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-3324f845c59f','SAT','math','mcq',3,NULL,'A bag contains 6 red marbles, 2 blue marbles, and 8 green marbles. One marble is chosen at random. What is the probability that it is blue?',NULL,'["1/8","6/16","2/14","8/16"]',0,'2 of 16 marbles are blue.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-bebad988bcec','SAT','math','mcq',3,NULL,'The equation of a circle in the xy-plane is (x − 0)² + (y + 1)² = 64. What is the radius of the circle?',NULL,'["16","8","64","9"]',1,'r² = 64, so r = 8.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-6dec4fb43754','SAT','math','mcq',2,NULL,'A technician charges a $34 fee plus $34 per hour. What is the total charge, in dollars, for a 2-hour job?',NULL,'["136","102","70"]',1,'34 + 34 × 2.',1,0);
