INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-wida-reading-f6d7b4794efc','WIDA','reading','mcq',1,NULL,'240 students were surveyed. How many students chose "Soup"?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" width="340" height="230" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><text x="170" y="18" text-anchor="middle" font-weight="700" font-size="13">Survey results</text><path d="M110 130 L110.0 52.0 A78 78 0 0 1 173.1 175.8 Z" fill="#059669" stroke="#fff" stroke-width="2"/><text x="153.1" y="112.0" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">35%</text><rect x="215" y="58" width="12" height="12" rx="3" fill="#059669"/><text x="234" y="69" font-size="12">Pizza</text><path d="M110 130 L173.1 175.8 A78 78 0 0 1 134.1 204.2 Z" fill="#0ea5e9" stroke="#fff" stroke-width="2"/><text x="138.4" y="173.1" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">10%</text><rect x="215" y="82" width="12" height="12" rx="3" fill="#0ea5e9"/><text x="234" y="93" font-size="12">Pasta</text><path d="M110 130 L134.1 204.2 A78 78 0 0 1 35.8 154.1 Z" fill="#10b981" stroke="#fff" stroke-width="2"/><text x="88.0" y="177.1" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">25%</text><rect x="215" y="106" width="12" height="12" rx="3" fill="#10b981"/><text x="234" y="117" font-size="12">Salad</text><path d="M110 130 L35.8 154.1 A78 78 0 0 1 110.0 52.0 Z" fill="#f59e0b" stroke="#fff" stroke-width="2"/><text x="70.9" y="105.6" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">30%</text><rect x="215" y="130" width="12" height="12" rx="3" fill="#f59e0b"/><text x="234" y="141" font-size="12">Soup</text></svg>','["30","62","82","72"]',3,'30% of 240 = 72.',1,0);
