INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-ad0decabe93a','TOEFLJ','reading','mcq',3,NULL,'Which bus takes the least time to reach the museum?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 290 144" width="290" height="144" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><text x="145" y="18" text-anchor="middle" font-weight="700" font-size="13">School trip bus schedule (morning)</text><rect x="10" y="28" width="270" height="26" fill="#e5e7eb" stroke="#e5e7eb"/><text x="55" y="45" text-anchor="middle" font-size="12" font-weight="700">Bus</text><text x="145" y="45" text-anchor="middle" font-size="12" font-weight="700">Leaves</text><text x="235" y="45" text-anchor="middle" font-size="12" font-weight="700">Arrives</text><rect x="10" y="54" width="270" height="26" fill="#fff" stroke="#e5e7eb"/><text x="55" y="71" text-anchor="middle" font-size="12" >Bus A</text><text x="145" y="71" text-anchor="middle" font-size="12" >9:30</text><text x="235" y="71" text-anchor="middle" font-size="12" >10:05</text><rect x="10" y="80" width="270" height="26" fill="#f9fafb" stroke="#e5e7eb"/><text x="55" y="97" text-anchor="middle" font-size="12" >Bus B</text><text x="145" y="97" text-anchor="middle" font-size="12" >10:20</text><text x="235" y="97" text-anchor="middle" font-size="12" >11:00</text><rect x="10" y="106" width="270" height="26" fill="#fff" stroke="#e5e7eb"/><text x="55" y="123" text-anchor="middle" font-size="12" >Bus C</text><text x="145" y="123" text-anchor="middle" font-size="12" >10:40</text><text x="235" y="123" text-anchor="middle" font-size="12" >11:05</text></svg>','["They all take the same time","Bus B","Bus C","Bus A"]',2,'Bus C takes 25 minutes, the shortest trip.',1,0);
