INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-b6b2cb16397d','CAT4','verbal','mcq',4,NULL,'Some students in the club play chess. All students who play chess are in Year 7. Which statement MUST be true?',NULL,'["No Year 7 students play chess.","All club students are in Year 7.","All Year 7 students are in the club.","Some club students are in Year 7."]',3,'The club members who play chess are in Year 7, so at least some club students are.',1,0);
