INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-ad2ad3593952','CAT4','verbal','mcq',5,NULL,'Which word is the opposite of benevolent?',NULL,'["aloof","timid","generous","malicious"]',3,'Benevolent means well-meaning and malicious means intending harm.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-cat4-verbal-ed13373450a9','CAT4','verbal','mcq',5,NULL,'No reptiles are warm-blooded. Some pets are reptiles. Which statement MUST be true?',NULL,'["No pets are warm-blooded.","Some pets are not warm-blooded.","Some warm-blooded animals are reptiles.","All pets are reptiles."]',1,'The pets that are reptiles cannot be warm-blooded.',1,0);
