INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-verbal-1c034e23d21f','ISEE','verbal','mcq',2,NULL,'The ___ heat of the desert made travel ___ during the afternoon.',NULL,'["scorching ... delightful","scorching ... grueling","mild ... grueling","mild ... pleasant"]',1,'Scorching heat would make afternoon travel grueling.',1,0);
