INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-verbal-d17bc2304038','ISEE','verbal','mcq',5,NULL,'Though the diplomat''s manner was ___, her proposals were ruthlessly firm.',NULL,'["truculent","dogmatic","inflexible","affable"]',3,'Though signals contrast, so a friendly (affable) manner contrasts with firm proposals.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-verbal-ffc5798c2d57','ISEE','verbal','mcq',5,NULL,'Not content with ___ praise, the ambitious young poet craved ___ acclaim.',NULL,'["scant ... scarce","lavish ... meager","modest ... universal","widespread ... modest"]',2,'An ambitious person unsatisfied with modest praise would crave universal acclaim.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-verbal-0168650e4da1','ISEE','verbal','mcq',4,NULL,'Her ___ response to the crisis, neither panicking nor hesitating, earned her the board''s trust.',NULL,'["impetuous","frantic","measured","indecisive"]',2,'Neither panicking nor hesitating describes a measured response.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-0c6d0ae3eaea','ISEE','reading','mcq',2,'Every morning, Marisol climbed the narrow stairs to her grandfather''s workshop, where dozens of clocks ticked out of step with one another. As a small child she had found the noise maddening, but now she barely heard it. Her grandfather, bent over a brass gear no larger than a coin, never looked up when she entered. "Hand me the tweezers," he would say, and she would, and that was their entire conversation until noon. Yet she had come to understand that this silence was not coldness. It was the way he welcomed her: by assuming she belonged there. When a customer once asked why such a quiet girl bothered to visit, her grandfather answered without lifting his eyes. "She is the only one who knows when to stay still," he said. Marisol pretended to polish a clock face, but her cheeks burned with pride.','What is the passage mainly about?',NULL,'["A girl''s growing appreciation of her grandfather''s quiet way of showing acceptance","A customer''s complaint about a clock repair","A child''s frustration with a noisy workplace","The history of clockmaking in a small town"]',0,'The passage traces how Marisol comes to see her grandfather''s silence as welcome.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-50cc10ab16af','ISEE','reading','mcq',1,'Every morning, Marisol climbed the narrow stairs to her grandfather''s workshop, where dozens of clocks ticked out of step with one another. As a small child she had found the noise maddening, but now she barely heard it. Her grandfather, bent over a brass gear no larger than a coin, never looked up when she entered. "Hand me the tweezers," he would say, and she would, and that was their entire conversation until noon. Yet she had come to understand that this silence was not coldness. It was the way he welcomed her: by assuming she belonged there. When a customer once asked why such a quiet girl bothered to visit, her grandfather answered without lifting his eyes. "She is the only one who knows when to stay still," he said. Marisol pretended to polish a clock face, but her cheeks burned with pride.','What does Marisol''s grandfather usually say when she enters the workshop?',NULL,'["Good morning","Hand me the tweezers","Why have you come","Stay still"]',1,'The passage quotes him asking for the tweezers.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-cc4542d02f84','ISEE','reading','mcq',3,'Every morning, Marisol climbed the narrow stairs to her grandfather''s workshop, where dozens of clocks ticked out of step with one another. As a small child she had found the noise maddening, but now she barely heard it. Her grandfather, bent over a brass gear no larger than a coin, never looked up when she entered. "Hand me the tweezers," he would say, and she would, and that was their entire conversation until noon. Yet she had come to understand that this silence was not coldness. It was the way he welcomed her: by assuming she belonged there. When a customer once asked why such a quiet girl bothered to visit, her grandfather answered without lifting his eyes. "She is the only one who knows when to stay still," he said. Marisol pretended to polish a clock face, but her cheeks burned with pride.','The statement that Marisol''s "cheeks burned with pride" suggests that she was',NULL,'["tired from polishing","pleased by her grandfather''s compliment","embarrassed by the customer''s question","angry at her grandfather"]',1,'Pride shows she was happy about his praise.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-6ed9b94fd419','ISEE','reading','mcq',3,'Every morning, Marisol climbed the narrow stairs to her grandfather''s workshop, where dozens of clocks ticked out of step with one another. As a small child she had found the noise maddening, but now she barely heard it. Her grandfather, bent over a brass gear no larger than a coin, never looked up when she entered. "Hand me the tweezers," he would say, and she would, and that was their entire conversation until noon. Yet she had come to understand that this silence was not coldness. It was the way he welcomed her: by assuming she belonged there. When a customer once asked why such a quiet girl bothered to visit, her grandfather answered without lifting his eyes. "She is the only one who knows when to stay still," he said. Marisol pretended to polish a clock face, but her cheeks burned with pride.','As used in the passage, "maddening" most nearly means',NULL,'["mysterious","extremely irritating","rhythmic","pleasant"]',1,'She once disliked the noise, so maddening means very irritating.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-e06be4e66471','ISEE','reading','mcq',3,'Octopuses are masters of disguise, but the mechanism behind their transformations is stranger than most people realize. Beneath an octopus''s skin lie thousands of tiny sacs of pigment called chromatophores, each surrounded by muscles. When the animal wants to change color, its brain signals the muscles to stretch the sacs open or squeeze them shut, altering the pattern across its body within a fraction of a second. Remarkably, octopuses appear to be colorblind; their eyes contain only one type of light-sensing cell. Researchers therefore puzzle over how the animal matches its background so well. One hypothesis is that the skin itself contains light-sensitive proteins that detect surroundings directly, allowing the octopus to "see" with its body. Although the idea remains unproven, laboratory studies have shown that isolated patches of skin react when exposed to light, lending the theory some support.','Which statement best expresses the main idea of the passage?',NULL,'["Octopuses are the most intelligent sea animals.","Laboratory research is more reliable than field research.","Colorblind animals cannot hide from predators.","Octopuses change color using pigment sacs, yet how they match their backgrounds remains puzzling."]',3,'The passage explains the color mechanism and then raises the open question.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-ac0144959efb','ISEE','reading','mcq',2,'Octopuses are masters of disguise, but the mechanism behind their transformations is stranger than most people realize. Beneath an octopus''s skin lie thousands of tiny sacs of pigment called chromatophores, each surrounded by muscles. When the animal wants to change color, its brain signals the muscles to stretch the sacs open or squeeze them shut, altering the pattern across its body within a fraction of a second. Remarkably, octopuses appear to be colorblind; their eyes contain only one type of light-sensing cell. Researchers therefore puzzle over how the animal matches its background so well. One hypothesis is that the skin itself contains light-sensitive proteins that detect surroundings directly, allowing the octopus to "see" with its body. Although the idea remains unproven, laboratory studies have shown that isolated patches of skin react when exposed to light, lending the theory some support.','According to the passage, what causes the pigment sacs to open or close?',NULL,'["Muscles signaled by the brain","Light-sensitive proteins","Changes in water temperature","Chemicals released by predators"]',0,'Muscles around the sacs respond to signals from the brain.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-8e5c4f982093','ISEE','reading','mcq',4,'Octopuses are masters of disguise, but the mechanism behind their transformations is stranger than most people realize. Beneath an octopus''s skin lie thousands of tiny sacs of pigment called chromatophores, each surrounded by muscles. When the animal wants to change color, its brain signals the muscles to stretch the sacs open or squeeze them shut, altering the pattern across its body within a fraction of a second. Remarkably, octopuses appear to be colorblind; their eyes contain only one type of light-sensing cell. Researchers therefore puzzle over how the animal matches its background so well. One hypothesis is that the skin itself contains light-sensitive proteins that detect surroundings directly, allowing the octopus to "see" with its body. Although the idea remains unproven, laboratory studies have shown that isolated patches of skin react when exposed to light, lending the theory some support.','Why do researchers find the octopus''s ability to match its background puzzling?',NULL,'["Its skin contains no pigment","It rarely changes color","Its brain is unusually small","Its eyes seem unable to perceive color"]',3,'The animal appears colorblind yet matches colors well.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-fe028019528c','ISEE','reading','mcq',3,'Octopuses are masters of disguise, but the mechanism behind their transformations is stranger than most people realize. Beneath an octopus''s skin lie thousands of tiny sacs of pigment called chromatophores, each surrounded by muscles. When the animal wants to change color, its brain signals the muscles to stretch the sacs open or squeeze them shut, altering the pattern across its body within a fraction of a second. Remarkably, octopuses appear to be colorblind; their eyes contain only one type of light-sensing cell. Researchers therefore puzzle over how the animal matches its background so well. One hypothesis is that the skin itself contains light-sensitive proteins that detect surroundings directly, allowing the octopus to "see" with its body. Although the idea remains unproven, laboratory studies have shown that isolated patches of skin react when exposed to light, lending the theory some support.','As used in the passage, "hypothesis" most nearly means',NULL,'["a historical record","a proposed explanation","a final conclusion","a measurement"]',1,'The idea is described as unproven, so it is a proposed explanation.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-0cdff2a1e120','ISEE','reading','mcq',3,'Before the Erie Canal opened in 1825, shipping a ton of goods from Buffalo to New York City cost about one hundred dollars and took weeks of jolting travel by wagon. The canal, a 363-mile waterway dug largely by hand, cut that cost to roughly ten dollars and shortened the trip considerably. Farmers in the Midwest suddenly found that their grain could reach eastern markets profitably, and they planted more. Towns such as Rochester and Syracuse grew rapidly along the route, and New York City surpassed rival ports to become the nation''s busiest. Not everyone benefited, however. Farmers in New England, facing cheaper western produce, struggled to compete, and many abandoned their land for factory jobs or for the West itself. The canal thus illustrates how a single improvement in transportation can reshape the economy, creating winners and losers at the same time.','Which statement best expresses the main idea of the passage?',NULL,'["The Erie Canal reshaped the economy, helping some regions while hurting others.","The Erie Canal was the longest waterway ever built.","Wagon travel was safer than canal travel.","New England farmers invented new crops."]',0,'The passage describes both gains and losses from the canal.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-a8105f5b3ef5','ISEE','reading','mcq',2,'Before the Erie Canal opened in 1825, shipping a ton of goods from Buffalo to New York City cost about one hundred dollars and took weeks of jolting travel by wagon. The canal, a 363-mile waterway dug largely by hand, cut that cost to roughly ten dollars and shortened the trip considerably. Farmers in the Midwest suddenly found that their grain could reach eastern markets profitably, and they planted more. Towns such as Rochester and Syracuse grew rapidly along the route, and New York City surpassed rival ports to become the nation''s busiest. Not everyone benefited, however. Farmers in New England, facing cheaper western produce, struggled to compete, and many abandoned their land for factory jobs or for the West itself. The canal thus illustrates how a single improvement in transportation can reshape the economy, creating winners and losers at the same time.','According to the passage, the canal changed the cost of shipping a ton of goods from Buffalo to New York City by about how much?',NULL,'["From ten dollars to one dollar","From one hundred dollars to fifty dollars","From one hundred dollars to ten dollars","It did not change the cost"]',2,'The passage gives about one hundred dollars before and ten dollars after.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-27d19ecc585f','ISEE','reading','mcq',4,'Before the Erie Canal opened in 1825, shipping a ton of goods from Buffalo to New York City cost about one hundred dollars and took weeks of jolting travel by wagon. The canal, a 363-mile waterway dug largely by hand, cut that cost to roughly ten dollars and shortened the trip considerably. Farmers in the Midwest suddenly found that their grain could reach eastern markets profitably, and they planted more. Towns such as Rochester and Syracuse grew rapidly along the route, and New York City surpassed rival ports to become the nation''s busiest. Not everyone benefited, however. Farmers in New England, facing cheaper western produce, struggled to compete, and many abandoned their land for factory jobs or for the West itself. The canal thus illustrates how a single improvement in transportation can reshape the economy, creating winners and losers at the same time.','Why did many New England farmers leave their land?',NULL,'["Wagon travel was banned.","They could not compete with cheaper western produce.","Their land was flooded by the canal.","They were hired to dig the canal."]',1,'The passage says they struggled against cheaper western produce.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-ffad8757f28a','ISEE','reading','mcq',3,'Before the Erie Canal opened in 1825, shipping a ton of goods from Buffalo to New York City cost about one hundred dollars and took weeks of jolting travel by wagon. The canal, a 363-mile waterway dug largely by hand, cut that cost to roughly ten dollars and shortened the trip considerably. Farmers in the Midwest suddenly found that their grain could reach eastern markets profitably, and they planted more. Towns such as Rochester and Syracuse grew rapidly along the route, and New York City surpassed rival ports to become the nation''s busiest. Not everyone benefited, however. Farmers in New England, facing cheaper western produce, struggled to compete, and many abandoned their land for factory jobs or for the West itself. The canal thus illustrates how a single improvement in transportation can reshape the economy, creating winners and losers at the same time.','The final sentence of the passage serves to',NULL,'["draw a general lesson from the specific case","introduce a new historical event","criticize the builders of the canal","present a counterexample"]',0,'It generalizes from the canal to transportation improvements in general.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-9631290c336d','ISEE','reading','mcq',4,'Translators are often described as invisible, and the best are said to be those whose work readers never notice. Yet this ideal is more contested than it appears. A translator who renders a novel into smooth, natural English may erase the strangeness that made the original distinctive; the foreign rhythms, unfamiliar idioms, and odd turns of phrase are, after all, part of what the author intended. Some contemporary translators therefore deliberately preserve awkwardness, trusting readers to tolerate friction in exchange for authenticity. Critics reply that a translation no one can comfortably read has failed its audience as surely as one that distorts the original. The disagreement is unlikely to be settled, because it reflects a genuine tension between two loyalties: fidelity to the author and service to the reader. Every translator, in effect, must choose where to stand between them.','Which statement best expresses the main idea of the passage?',NULL,'["Translators should always remain invisible.","Translators face a genuine tension between faithfulness to the author and service to the reader.","Critics have proved that awkward translations fail.","Smooth translations are always inferior to awkward ones."]',1,'The passage ends by naming this tension as the core of the disagreement.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-c5d700547b4b','ISEE','reading','mcq',4,'Translators are often described as invisible, and the best are said to be those whose work readers never notice. Yet this ideal is more contested than it appears. A translator who renders a novel into smooth, natural English may erase the strangeness that made the original distinctive; the foreign rhythms, unfamiliar idioms, and odd turns of phrase are, after all, part of what the author intended. Some contemporary translators therefore deliberately preserve awkwardness, trusting readers to tolerate friction in exchange for authenticity. Critics reply that a translation no one can comfortably read has failed its audience as surely as one that distorts the original. The disagreement is unlikely to be settled, because it reflects a genuine tension between two loyalties: fidelity to the author and service to the reader. Every translator, in effect, must choose where to stand between them.','As used in the passage, "contested" most nearly means',NULL,'["disputed","widely accepted","ignored","simple"]',0,'The ideal is called more contested than it appears, meaning argued over.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-708ae02c6920','ISEE','reading','mcq',4,'Translators are often described as invisible, and the best are said to be those whose work readers never notice. Yet this ideal is more contested than it appears. A translator who renders a novel into smooth, natural English may erase the strangeness that made the original distinctive; the foreign rhythms, unfamiliar idioms, and odd turns of phrase are, after all, part of what the author intended. Some contemporary translators therefore deliberately preserve awkwardness, trusting readers to tolerate friction in exchange for authenticity. Critics reply that a translation no one can comfortably read has failed its audience as surely as one that distorts the original. The disagreement is unlikely to be settled, because it reflects a genuine tension between two loyalties: fidelity to the author and service to the reader. Every translator, in effect, must choose where to stand between them.','The author''s tone in discussing the debate is best described as',NULL,'["dismissive and sarcastic","even-handed and reflective","angry and defensive","nostalgic and wistful"]',1,'The author presents both sides without favoring either.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-ccae5609b6c5','ISEE','reading','mcq',5,'Translators are often described as invisible, and the best are said to be those whose work readers never notice. Yet this ideal is more contested than it appears. A translator who renders a novel into smooth, natural English may erase the strangeness that made the original distinctive; the foreign rhythms, unfamiliar idioms, and odd turns of phrase are, after all, part of what the author intended. Some contemporary translators therefore deliberately preserve awkwardness, trusting readers to tolerate friction in exchange for authenticity. Critics reply that a translation no one can comfortably read has failed its audience as surely as one that distorts the original. The disagreement is unlikely to be settled, because it reflects a genuine tension between two loyalties: fidelity to the author and service to the reader. Every translator, in effect, must choose where to stand between them.','According to the passage, why might a very smooth translation be a problem?',NULL,'["It may erase the strangeness that was part of the original''s character.","It always contains errors of grammar.","It is rejected by all critics.","It requires translators to be visible."]',0,'The passage says smoothness may erase what made the original distinctive.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-41fa2011bc5d','ISEE','reading','mcq',2,'The bus hissed to a stop, and Daniel stepped onto the unfamiliar sidewalk with his duffel bag clutched against his chest. The town looked smaller than the photographs his aunt had sent: one traffic light, a bakery with a faded awning, and a hardware store whose windows were crowded with ladders. He told himself that smaller was better, that fewer streets meant fewer ways to get lost. But when his aunt''s old truck rattled around the corner and she leaned out the window, waving both arms as if flagging down a ship, something in his chest loosened. For the first time in weeks, he laughed.','Daniel''s feelings upon arriving can best be described as',NULL,'["confident and bored","uneasy at first, then relieved","joyful from the start","angry and resentful"]',1,'He reassures himself nervously, then relaxes and laughs on seeing his aunt.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-d810109a6a88','ISEE','reading','mcq',1,'The bus hissed to a stop, and Daniel stepped onto the unfamiliar sidewalk with his duffel bag clutched against his chest. The town looked smaller than the photographs his aunt had sent: one traffic light, a bakery with a faded awning, and a hardware store whose windows were crowded with ladders. He told himself that smaller was better, that fewer streets meant fewer ways to get lost. But when his aunt''s old truck rattled around the corner and she leaned out the window, waving both arms as if flagging down a ship, something in his chest loosened. For the first time in weeks, he laughed.','How does Daniel''s aunt greet him?',NULL,'["By waiting silently","By waving both arms from her truck","By hugging him at the bus stop","By sending a letter"]',1,'She leans out the truck window waving both arms.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-d47764344694','ISEE','reading','mcq',3,'The bus hissed to a stop, and Daniel stepped onto the unfamiliar sidewalk with his duffel bag clutched against his chest. The town looked smaller than the photographs his aunt had sent: one traffic light, a bakery with a faded awning, and a hardware store whose windows were crowded with ladders. He told himself that smaller was better, that fewer streets meant fewer ways to get lost. But when his aunt''s old truck rattled around the corner and she leaned out the window, waving both arms as if flagging down a ship, something in his chest loosened. For the first time in weeks, he laughed.','As used in the passage, "loosened" most nearly means',NULL,'["came apart","relaxed","hurt","broke"]',1,'His tension eased when he saw her, so loosened means relaxed.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-03271bb57098','ISEE','reading','mcq',2,'When a honeybee finds a rich patch of flowers, it returns to the hive and performs a "waggle dance" to share the news. The bee shuffles in a figure-eight pattern, vibrating its abdomen during the straight middle section. The angle of this waggle run, measured against the vertical wall of the comb, tells the other bees which direction to fly relative to the sun. The length of the run indicates distance: the longer the waggle, the farther away the food. Observers in dark hives have confirmed that the bees follow these instructions with surprising accuracy, even when the sun is hidden behind clouds. Scientists consider the dance remarkable because few animals other than humans communicate information about things that are not present.','What is the passage mainly about?',NULL,'["Why bees vibrate their wings to keep warm","How honeybees use a dance to communicate the location of food","How the sun affects the growth of flowers","Why honeybees build hives in the dark"]',1,'The whole passage describes the waggle dance and what it tells other bees.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-5d5bbbc09502','ISEE','reading','mcq',2,'When a honeybee finds a rich patch of flowers, it returns to the hive and performs a "waggle dance" to share the news. The bee shuffles in a figure-eight pattern, vibrating its abdomen during the straight middle section. The angle of this waggle run, measured against the vertical wall of the comb, tells the other bees which direction to fly relative to the sun. The length of the run indicates distance: the longer the waggle, the farther away the food. Observers in dark hives have confirmed that the bees follow these instructions with surprising accuracy, even when the sun is hidden behind clouds. Scientists consider the dance remarkable because few animals other than humans communicate information about things that are not present.','According to the passage, what does the length of the waggle run indicate?',NULL,'["The direction of the sun","How far away the food is","The time of day","The quality of the nectar"]',1,'The passage states that a longer waggle means farther food.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-cba57de81d7a','ISEE','reading','mcq',3,'When a honeybee finds a rich patch of flowers, it returns to the hive and performs a "waggle dance" to share the news. The bee shuffles in a figure-eight pattern, vibrating its abdomen during the straight middle section. The angle of this waggle run, measured against the vertical wall of the comb, tells the other bees which direction to fly relative to the sun. The length of the run indicates distance: the longer the waggle, the farther away the food. Observers in dark hives have confirmed that the bees follow these instructions with surprising accuracy, even when the sun is hidden behind clouds. Scientists consider the dance remarkable because few animals other than humans communicate information about things that are not present.','Why do scientists consider the dance remarkable?',NULL,'["It is performed outdoors.","It conveys information about things that are not present, which few animals besides humans do.","It is the only form of communication among insects.","It requires bees to see the sun."]',1,'The last sentence gives this as the reason.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-1bb359169cb6','ISEE','reading','mcq',4,'In the early nineteenth century, a person who wished to read widely had few options. Books were expensive, and most were owned by the wealthy or housed in private subscription libraries that charged steep annual fees. The idea of a free public library, supported by local taxes and open to anyone, struck many citizens as both unnecessary and unfair; why, they asked, should a shopkeeper pay for books that a lawyer would read? Advocates answered that an educated population benefited everyone, much as paved roads and clean water did. Gradually this argument prevailed. By the end of the century, hundreds of towns had established libraries, and reading, once a mark of privilege, had become an ordinary part of civic life.','How does the author develop the passage?',NULL,'["By telling one citizen''s story","By listing famous libraries in order of size","By describing an earlier situation, the objections to a change, and the eventual outcome","By comparing two kinds of books"]',2,'The passage moves from limited access to objections to the eventual spread of libraries.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-9590c2f6ce93','ISEE','reading','mcq',3,'In the early nineteenth century, a person who wished to read widely had few options. Books were expensive, and most were owned by the wealthy or housed in private subscription libraries that charged steep annual fees. The idea of a free public library, supported by local taxes and open to anyone, struck many citizens as both unnecessary and unfair; why, they asked, should a shopkeeper pay for books that a lawyer would read? Advocates answered that an educated population benefited everyone, much as paved roads and clean water did. Gradually this argument prevailed. By the end of the century, hundreds of towns had established libraries, and reading, once a mark of privilege, had become an ordinary part of civic life.','According to the passage, what was one objection to free public libraries?',NULL,'["Private libraries would charge more.","Taxes would pay for books that some citizens might not use.","Libraries would be too noisy.","Wealthy people would stop reading."]',1,'Critics asked why a shopkeeper should pay for books a lawyer would read.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-4eee9f4562c9','ISEE','reading','mcq',4,'In the early nineteenth century, a person who wished to read widely had few options. Books were expensive, and most were owned by the wealthy or housed in private subscription libraries that charged steep annual fees. The idea of a free public library, supported by local taxes and open to anyone, struck many citizens as both unnecessary and unfair; why, they asked, should a shopkeeper pay for books that a lawyer would read? Advocates answered that an educated population benefited everyone, much as paved roads and clean water did. Gradually this argument prevailed. By the end of the century, hundreds of towns had established libraries, and reading, once a mark of privilege, had become an ordinary part of civic life.','As used in the passage, "prevailed" most nearly means',NULL,'["delayed","succeeded","lost","vanished"]',1,'The argument gradually won out, so prevailed means succeeded.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-214c1884fbff','ISEE','reading','mcq',4,'In the early nineteenth century, a person who wished to read widely had few options. Books were expensive, and most were owned by the wealthy or housed in private subscription libraries that charged steep annual fees. The idea of a free public library, supported by local taxes and open to anyone, struck many citizens as both unnecessary and unfair; why, they asked, should a shopkeeper pay for books that a lawyer would read? Advocates answered that an educated population benefited everyone, much as paved roads and clean water did. Gradually this argument prevailed. By the end of the century, hundreds of towns had established libraries, and reading, once a mark of privilege, had become an ordinary part of civic life.','The comparison to paved roads and clean water serves to',NULL,'["suggest that roads and water are less important","show that libraries were cheaper than roads","suggest that libraries, like other public goods, benefit everyone","amuse the reader with an unlikely comparison"]',2,'Advocates used the comparison to argue that libraries serve the whole community.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-9a1244679d63','ISEE','reading','mcq',2,'Seventeenth-century Dutch painters turned away from the grand religious and mythological scenes that had dominated European art. Instead, a rising merchant class wanted pictures of their own world: a woman pouring milk, a tavern crowded with card players, a quiet street after rain. Such works were modest in scale, since they were meant to hang in ordinary homes rather than cathedrals. Yet their apparent simplicity is deceptive. Painters labored over the fall of light on a copper pot or the texture of a linen cloth, convinced that attention to the everyday could reveal something enduring. Some scholars read hidden moral lessons into these scenes, such as warnings against idleness or excess. Others argue that the paintings celebrate ordinary life for its own sake. Probably both views contain some truth, for the artists seldom explained themselves.','According to the passage, why were these paintings modest in scale?',NULL,'["Churches forbade large canvases.","Painters lacked skill.","Paint was scarce.","They were meant to hang in ordinary homes."]',3,'The passage says they were meant for ordinary homes rather than cathedrals.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-62ca44c44fcc','ISEE','reading','mcq',4,'Seventeenth-century Dutch painters turned away from the grand religious and mythological scenes that had dominated European art. Instead, a rising merchant class wanted pictures of their own world: a woman pouring milk, a tavern crowded with card players, a quiet street after rain. Such works were modest in scale, since they were meant to hang in ordinary homes rather than cathedrals. Yet their apparent simplicity is deceptive. Painters labored over the fall of light on a copper pot or the texture of a linen cloth, convinced that attention to the everyday could reveal something enduring. Some scholars read hidden moral lessons into these scenes, such as warnings against idleness or excess. Others argue that the paintings celebrate ordinary life for its own sake. Probably both views contain some truth, for the artists seldom explained themselves.','As used in the passage, "deceptive" most nearly means',NULL,'["misleading","obvious","pleasing","honest"]',0,'The simplicity hides the painters'' great effort, so it is misleading.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-86e9af467cf1','ISEE','reading','mcq',5,'Seventeenth-century Dutch painters turned away from the grand religious and mythological scenes that had dominated European art. Instead, a rising merchant class wanted pictures of their own world: a woman pouring milk, a tavern crowded with card players, a quiet street after rain. Such works were modest in scale, since they were meant to hang in ordinary homes rather than cathedrals. Yet their apparent simplicity is deceptive. Painters labored over the fall of light on a copper pot or the texture of a linen cloth, convinced that attention to the everyday could reveal something enduring. Some scholars read hidden moral lessons into these scenes, such as warnings against idleness or excess. Others argue that the paintings celebrate ordinary life for its own sake. Probably both views contain some truth, for the artists seldom explained themselves.','The author suggests that the two scholarly interpretations',NULL,'["are probably both partly correct","are impossible to reconcile","have been disproved","are unrelated to the paintings"]',0,'The author says both views probably contain some truth.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-reading-7dfc242db07b','ISEE','reading','mcq',3,'Seventeenth-century Dutch painters turned away from the grand religious and mythological scenes that had dominated European art. Instead, a rising merchant class wanted pictures of their own world: a woman pouring milk, a tavern crowded with card players, a quiet street after rain. Such works were modest in scale, since they were meant to hang in ordinary homes rather than cathedrals. Yet their apparent simplicity is deceptive. Painters labored over the fall of light on a copper pot or the texture of a linen cloth, convinced that attention to the everyday could reveal something enduring. Some scholars read hidden moral lessons into these scenes, such as warnings against idleness or excess. Others argue that the paintings celebrate ordinary life for its own sake. Probably both views contain some truth, for the artists seldom explained themselves.','Which statement best expresses the main idea of the passage?',NULL,'["Dutch painters of this era depicted everyday life with care for a new merchant audience.","Merchants refused to buy art.","Dutch painters rejected the use of light.","Religious art vanished from Europe."]',0,'The passage describes the shift to everyday subjects and why they were painted.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-0f47152eb905','MAP','reading','mcq',1,'Ben has a little dog named Pip. Pip has brown spots and a short tail. Every morning, Ben gives Pip a bowl of food. Then they go for a walk in the park. Pip likes to chase red balls. At night, Pip sleeps in a soft bed next to Ben''s bed.','What is the name of Ben''s dog?',NULL,'["Max","Ben","Pip","Spot"]',2,'The first sentence says Ben has a little dog named Pip.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-d80680f49dee','MAP','reading','mcq',1,'Ben has a little dog named Pip. Pip has brown spots and a short tail. Every morning, Ben gives Pip a bowl of food. Then they go for a walk in the park. Pip likes to chase red balls. At night, Pip sleeps in a soft bed next to Ben''s bed.','What does Ben do first every morning?',NULL,'["He gives Pip a bowl of food.","He throws a red ball.","He goes to bed.","He walks Pip in the park."]',0,'The passage says Ben feeds Pip every morning and then they go for a walk.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-7860b1e0891e','MAP','reading','mcq',2,'Ben has a little dog named Pip. Pip has brown spots and a short tail. Every morning, Ben gives Pip a bowl of food. Then they go for a walk in the park. Pip likes to chase red balls. At night, Pip sleeps in a soft bed next to Ben''s bed.','Where does Pip sleep at night?',NULL,'["On the kitchen floor","In a soft bed next to Ben''s bed","In the park","In a box outside"]',1,'The last sentence says Pip sleeps in a soft bed next to Ben''s bed.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-d6dc2ecb1c25','MAP','reading','mcq',1,'It was a cold day. Gray clouds filled the sky. Soon, white flakes began to fall. Mia put on her coat, hat, and mittens. She ran outside and made a big snowman. She gave it a carrot nose. Then her hands felt cold, so she went inside for hot cocoa.','What was falling from the sky?',NULL,'["Sand","Snow","Leaves","Rain"]',1,'White flakes fell on a cold day and Mia made a snowman, so it was snow.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-609497f3d7f8','MAP','reading','mcq',2,'It was a cold day. Gray clouds filled the sky. Soon, white flakes began to fall. Mia put on her coat, hat, and mittens. She ran outside and made a big snowman. She gave it a carrot nose. Then her hands felt cold, so she went inside for hot cocoa.','Why did Mia go inside?',NULL,'["She wanted a carrot.","Her hands felt cold.","Her snowman fell down.","It got dark."]',1,'The passage says her hands felt cold, so she went inside.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-fb528a5f7949','MAP','reading','mcq',1,'It was a cold day. Gray clouds filled the sky. Soon, white flakes began to fall. Mia put on her coat, hat, and mittens. She ran outside and made a big snowman. She gave it a carrot nose. Then her hands felt cold, so she went inside for hot cocoa.','What did Mia use for the snowman''s nose?',NULL,'["A carrot","A stick","A rock","A button"]',0,'The passage says she gave the snowman a carrot nose.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-6ef56e1d50f7','MAP','reading','mcq',2,'A seed is very small. When you put a seed in soil and give it water, it starts to grow. First, a tiny root grows down. Next, a green stem pushes up. Then leaves open up to take in sunlight. Plants need water, soil, and sun to grow.','What grows first from the seed?',NULL,'["A root","A stem","Leaves","A flower"]',0,'The passage says first a tiny root grows down.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-272201146fc7','MAP','reading','mcq',2,'A seed is very small. When you put a seed in soil and give it water, it starts to grow. First, a tiny root grows down. Next, a green stem pushes up. Then leaves open up to take in sunlight. Plants need water, soil, and sun to grow.','What is this passage mostly about?',NULL,'["How a seed grows into a plant","How to dig a hole","How to cook food","Why the sun is hot"]',0,'Every sentence tells about a seed growing a root, stem, and leaves.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-edf9a1e1bf61','MAP','reading','mcq',1,'A seed is very small. When you put a seed in soil and give it water, it starts to grow. First, a tiny root grows down. Next, a green stem pushes up. Then leaves open up to take in sunlight. Plants need water, soil, and sun to grow.','Which three things do plants need to grow?',NULL,'["Toys, cups, and books","Milk, sand, and wind","Rocks, snow, and dark","Water, soil, and sun"]',3,'The last sentence says plants need water, soil, and sun to grow.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-869e34030eff','MAP','reading','mcq',1,'Grandpa came to visit on Saturday. He brought a kite shaped like a fish. Lily and Grandpa went to the hill behind the house. The wind was strong. Grandpa held the string, and Lily ran fast. The fish kite flew high over the trees. Lily laughed and said it was the best day ever.','On what day did Grandpa visit?',NULL,'["Sunday","Saturday","Monday","Friday"]',1,'The first sentence says Grandpa came to visit on Saturday.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-62a69a1a89c3','MAP','reading','mcq',1,'Grandpa came to visit on Saturday. He brought a kite shaped like a fish. Lily and Grandpa went to the hill behind the house. The wind was strong. Grandpa held the string, and Lily ran fast. The fish kite flew high over the trees. Lily laughed and said it was the best day ever.','What shape was the kite?',NULL,'["A boat","A bird","A star","A fish"]',3,'The passage says the kite was shaped like a fish.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-6e09bdd76fd5','MAP','reading','mcq',2,'Grandpa came to visit on Saturday. He brought a kite shaped like a fish. Lily and Grandpa went to the hill behind the house. The wind was strong. Grandpa held the string, and Lily ran fast. The fish kite flew high over the trees. Lily laughed and said it was the best day ever.','How did Lily most likely feel at the end?',NULL,'["Sad","Scared","Angry","Happy"]',3,'Lily laughed and called it the best day ever, which shows she was happy.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-791548e407c4','MAP','reading','mcq',1,'Today is library day for Mr. Lee''s class. The children walk quietly down the hall. Each child may pick one book. Sam picks a book about sharks. Nora picks a book about trains. They will take the books home and bring them back next week.','Who picks a book about sharks?',NULL,'["Sam","Nora","Mr. Lee","Ava"]',0,'The passage says Sam picks a book about sharks.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-1c4daa5279b7','MAP','reading','mcq',2,'Today is library day for Mr. Lee''s class. The children walk quietly down the hall. Each child may pick one book. Sam picks a book about sharks. Nora picks a book about trains. They will take the books home and bring them back next week.','The children walk quietly down the hall. What does "quietly" mean?',NULL,'["In a sad way","With loud steps","Very fast","Without making much noise"]',3,'To walk quietly means to walk without making much noise.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-5cbe1064a9a5','MAP','reading','mcq',1,'Today is library day for Mr. Lee''s class. The children walk quietly down the hall. Each child may pick one book. Sam picks a book about sharks. Nora picks a book about trains. They will take the books home and bring them back next week.','When will the children bring the books back?',NULL,'["Next week","Tonight","Next year","Tomorrow"]',0,'The last sentence says they will bring the books back next week.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-2130be1ffd60','MAP','reading','mcq',1,'In fall, the air gets cooler. The leaves on many trees turn red, orange, and yellow. Then the leaves drop to the ground. Squirrels are busy. They gather nuts and hide them. The squirrels will eat the nuts in winter when food is hard to find.','What happens to many leaves in fall?',NULL,'["They turn blue.","They grow bigger.","They change color and drop.","They become flowers."]',2,'The passage says leaves turn red, orange, and yellow and then drop to the ground.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-476b67e4209a','MAP','reading','mcq',2,'In fall, the air gets cooler. The leaves on many trees turn red, orange, and yellow. Then the leaves drop to the ground. Squirrels are busy. They gather nuts and hide them. The squirrels will eat the nuts in winter when food is hard to find.','Why do squirrels hide nuts?',NULL,'["To eat them in winter","To give them to birds","To play a game","To plant new trees"]',0,'The passage says squirrels eat the nuts in winter when food is hard to find.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-414094ce4f78','MAP','reading','mcq',1,'In fall, the air gets cooler. The leaves on many trees turn red, orange, and yellow. Then the leaves drop to the ground. Squirrels are busy. They gather nuts and hide them. The squirrels will eat the nuts in winter when food is hard to find.','How does the air feel in fall?',NULL,'["Louder","Cooler","Hotter","Sweeter"]',1,'The first sentence says the air gets cooler in fall.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-c72217c2d179','MAP','reading','mcq',1,'A frog starts life as a tiny egg in a pond. The egg hatches into a tadpole. A tadpole has a tail and lives in the water. Slowly, the tadpole grows legs. Its tail gets shorter and shorter. At last, it becomes a frog that can hop on land.','What does a frog egg hatch into?',NULL,'["A tadpole","A turtle","A fish","A bug"]',0,'The passage says the egg hatches into a tadpole.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-925d56287464','MAP','reading','mcq',2,'A frog starts life as a tiny egg in a pond. The egg hatches into a tadpole. A tadpole has a tail and lives in the water. Slowly, the tadpole grows legs. Its tail gets shorter and shorter. At last, it becomes a frog that can hop on land.','What happens to the tadpole''s tail as it grows?',NULL,'["It gets shorter.","It splits in two.","It turns red.","It gets longer."]',0,'The passage says its tail gets shorter and shorter.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-8a03a86750a6','MAP','reading','mcq',1,'A frog starts life as a tiny egg in a pond. The egg hatches into a tadpole. A tadpole has a tail and lives in the water. Slowly, the tadpole grows legs. Its tail gets shorter and shorter. At last, it becomes a frog that can hop on land.','Where does a frog egg start out?',NULL,'["In a pond","In the sand","In a tree","In a nest"]',0,'The first sentence says a frog starts as a tiny egg in a pond.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-f052b659669e','MAP','reading','mcq',1,'Ava saw that the class fish tank was dirty. She told her teacher, Ms. Hill. Together they took out the fish and put it in a bowl. They washed the rocks and filled the tank with clean water. Then they put the fish back. The fish swam happily.','Who did Ava tell about the dirty tank?',NULL,'["Ms. Hill","Her friend","Her mom","The principal"]',0,'The passage says she told her teacher, Ms. Hill.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-38a5b1ba9515','MAP','reading','mcq',2,'Ava saw that the class fish tank was dirty. She told her teacher, Ms. Hill. Together they took out the fish and put it in a bowl. They washed the rocks and filled the tank with clean water. Then they put the fish back. The fish swam happily.','What did they do after they washed the rocks?',NULL,'["Bought a new fish","Told the teacher","Filled the tank with clean water","Took out the fish"]',2,'The passage says they washed the rocks and then filled the tank with clean water.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-f50b31bff73f','MAP','reading','mcq',2,'Ava saw that the class fish tank was dirty. She told her teacher, Ms. Hill. Together they took out the fish and put it in a bowl. They washed the rocks and filled the tank with clean water. Then they put the fish back. The fish swam happily.','What is the story mostly about?',NULL,'["Fishing at a lake","Cleaning the class fish tank","Feeding a cat","Buying a new pet"]',1,'The whole story tells how Ava and Ms. Hill cleaned the fish tank.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-c71b5d1def9b','MAP','reading','mcq',1,NULL,'Which word rhymes with "cat"?',NULL,'["hat","cup","sit","dog"]',0,'Cat and hat both end with the same sound, -at.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-2a5cc1d2fa54','MAP','reading','mcq',2,NULL,'Which word rhymes with "light"?',NULL,'["late","lamp","list","night"]',3,'Light and night both end with the same sound, -ight.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-273b05be60c9','MAP','reading','mcq',1,NULL,'What is the opposite of "big"?',NULL,'["round","long","small","tall"]',2,'Small means little, which is the opposite of big.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-38333edaad57','MAP','reading','mcq',1,NULL,'What is the opposite of "happy"?',NULL,'["sad","kind","glad","funny"]',0,'Sad is the feeling that is the opposite of happy.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-c7266f0eefab','MAP','reading','mcq',1,NULL,'Which word best completes the sentence? "I wear my ___ on my feet."',NULL,'["shoes","hat","gloves","scarf"]',0,'Shoes are worn on the feet; the other things are worn on the head, hands, or neck.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-3fa6b7ac44df','MAP','reading','mcq',2,NULL,'Which word means almost the same as "fast"?',NULL,'["slow","late","tall","quick"]',3,'Quick and fast both mean moving with speed.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-e14eefcb935f','MAP','reading','mcq',2,NULL,'Which word best completes the sentence? "Please ___ the door so the cat cannot get out."',NULL,'["close","sing","eat","open"]',0,'Closing the door keeps the cat from getting out.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-84c352c57bf2','MAP','reading','mcq',2,NULL,'Which word means the same as "under"?',NULL,'["near","below","above","over"]',1,'Below and under both mean lower than something.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-c8f1054d5e1f','MAP','language','mcq',1,NULL,'Which word in this sentence needs a capital letter? "My friend jake likes to swim."',NULL,'["likes","swim","jake","friend"]',2,'Jake is a person''s name, and names always begin with a capital letter.',1,0);
