INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-2b21b2f92ef9','MAP','language','mcq',1,NULL,'Which mark should go at the end? "I like to eat apples"',NULL,'["a question mark (?)","an apostrophe ('')","a period (.)","a comma (,)"]',2,'The sentence tells something, so it ends with a period.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-7db4129459f1','MAP','language','mcq',2,NULL,'Which sentence ends with the correct mark?',NULL,'["Can you help me","Can you help me.","Can you help me?","Can you help me,"]',2,'Can you help me asks a question, so it needs a question mark.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-10f06adf0a54','MAP','language','mcq',2,NULL,'Which sentence should end with an exclamation point (!)?',NULL,'["Look out, a bee is coming","We eat lunch at noon","My shirt is blue","Do you have a pencil"]',0,'Look out, a bee is coming shows strong feeling and warns someone, so it ends with an exclamation point.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-9c7829979a8f','MAP','language','mcq',1,NULL,'Which word means more than one dog?',NULL,'["dog","doggs","doges","dogs"]',3,'To make dog mean more than one, just add -s to get dogs.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-561eda73728d','MAP','language','mcq',1,NULL,'Which word best completes the sentence? "I see three ___."',NULL,'["boxs","boxes","boxies","box"]',1,'Words that end in x add -es to mean more than one, so box becomes boxes.',1,0);
