INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-1d9c57fdf9b6','MAP','language','mcq',2,NULL,'Which word best completes the sentence? "Many ___ ran across the yard."',NULL,'["mice","mouses","mouse","mices"]',0,'The word for more than one mouse is mice.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-fc7415b17fc0','MAP','language','mcq',1,NULL,'Which word best completes the sentence? "The cats ___ sleeping."',NULL,'["is","am","are","be"]',2,'Cats means more than one, so the sentence uses are.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-d4f3e958613a','MAP','language','mcq',1,NULL,'Which word best completes the sentence? "She ___ my best friend."',NULL,'["were","is","am","are"]',1,'She is one person, so the sentence uses is.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-57ccf3f87463','MAP','language','mcq',2,NULL,'Which word best completes the sentence? "Yesterday, we ___ at the beach."',NULL,'["are","was","is","were"]',3,'Yesterday tells about the past, and we goes with were.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-185a3a8d863d','MAP','language','mcq',2,NULL,'Which word best completes the sentence? "Last night, the moon ___ very bright."',NULL,'["were","was","is","are"]',1,'Last night tells about the past, and one moon goes with was.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-506a48166488','MAP','language','mcq',2,NULL,'Which word best completes the sentence? "Yesterday, Max ___ to the store."',NULL,'["walks","will walk","walking","walked"]',3,'Yesterday tells about the past, so the verb needs -ed: walked.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-b6fdf365b5b8','MAP','language','mcq',1,NULL,'Which word comes first in ABC order?',NULL,'["ant","cow","dog","bat"]',0,'Ant starts with a, which comes before b, c, and d.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-dcc8f536e240','MAP','language','mcq',2,NULL,'Which group of words is in ABC order?',NULL,'["sun, hat, cup","cup, sun, hat","cup, hat, sun","hat, cup, sun"]',2,'C comes before h, and h comes before s, so cup, hat, sun is in ABC order.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-e25a8ebaa286','MAP','language','mcq',2,NULL,'These words all start with b. Which one comes first in ABC order?',NULL,'["bag","bed","bus","big"]',0,'All four words start with b, so look at the second letter: a comes before e, i, and u.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-3a2cfa2f70b7','MAP','language','mcq',1,NULL,'Which sentence makes sense?',NULL,'["The bird sings in the tree.","The tree sings in the bird.","The bird in sings tree the.","Sings the bird tree in."]',0,'Only The bird sings in the tree has its words in an order that makes sense.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-language-e63b4eb5bd52','MAP','language','mcq',2,NULL,'Which is a complete sentence?',NULL,'["The girl kicked the ball.","Kicked the ball the.","The girl the ball.","Ball girl the kicked."]',0,'The girl kicked the ball tells who did something and what she did.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-4ffaae6fb722','MAP','reading','mcq',4,'The shop smelled of oil and old paper, and Mara had stopped noticing either by the third week. Her grandfather worked at the bench beneath the window, a loupe screwed into one eye, his breath slowed to the rhythm of whatever movement lay open before him. He did not speak while he worked, and at first Mara had taken his silence for disapproval. She had arrived in June with a suitcase and a sullen certainty that the summer was a punishment.

On Thursday a woman brought in a mantel clock wrapped in a bath towel. It had belonged to her mother, she said, and it had not run in eleven years. Her grandfather lifted it from the towel the way one might lift a sleeping cat.

"Will it be expensive?" the woman asked.

"It will be slow," he said, which was not an answer, though the woman seemed to accept it as one.

After she left, he slid the clock across the bench toward Mara. She stared at it. In three weeks he had let her sort screws, wind finished pieces, and sweep. He had never let her open anything.

"The case first," he said. "Then you tell me what you see. Not what you think. What you see."

Mara reached for the smallest screwdriver, and her hand, she noticed, was not quite steady.','The statement that "at first Mara had taken his silence for disapproval" suggests that Mara',NULL,'["thinks her grandfather is unhappy with his customers","suspects her grandfather cannot hear her well","has since come to understand her grandfather''s silence differently","still believes her grandfather resents her presence"]',2,'The words "at first" signal that Mara''s original interpretation of the silence as disapproval has since changed.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-6556e97ebe2b','MAP','reading','mcq',4,'The shop smelled of oil and old paper, and Mara had stopped noticing either by the third week. Her grandfather worked at the bench beneath the window, a loupe screwed into one eye, his breath slowed to the rhythm of whatever movement lay open before him. He did not speak while he worked, and at first Mara had taken his silence for disapproval. She had arrived in June with a suitcase and a sullen certainty that the summer was a punishment.

