INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-map-reading-61960010ca40','MAP','reading','mcq',5,'With four hundred meters left, Dev was in fifth place, and fifth place did not qualify for anything.

