INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-verbal-7d6618f15cdf','SSAT','verbal','mcq',3,NULL,'Choose the word closest in meaning to RIGID.',NULL,'["stiff","smooth","flexible","fragile"]',0,'Rigid means stiff and unable to bend.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-verbal-26539ca185b9','SSAT','verbal','mcq',4,NULL,'Choose the word closest in meaning to METICULOUS.',NULL,'["hurried","generous","painstaking","careless"]',2,'A meticulous worker is painstaking, taking great care with every detail.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-verbal-34121ec7f2be','SSAT','verbal','mcq',4,NULL,'Choose the word closest in meaning to AMBIGUOUS.',NULL,'["unclear","hostile","ambitious","obvious"]',0,'An ambiguous statement is unclear because it can be understood in more than one way.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-verbal-b50c27a57f00','SSAT','verbal','mcq',4,NULL,'Choose the word closest in meaning to DETER.',NULL,'["encourage","discourage","decide","deliver"]',1,'To deter is to discourage someone from acting, often through fear of consequences.',1,0);
