INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-verbal-db893619a590','SSAT','verbal','mcq',4,NULL,'Choose the word closest in meaning to INDIFFERENT.',NULL,'["angry","enthusiastic","identical","unconcerned"]',3,'Indifferent means having no interest or concern, so unconcerned is closest.',1,0);
