INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-123d94b97ad2','TOEFLJ','listening','mcq',1,'Tom: Hi, Anna. Do you want to play soccer after school?
Anna: Sorry, Tom. I can''t. I have a piano lesson today.
Tom: Okay. How about tomorrow?
Anna: Yes! Tomorrow is good.','Why can''t Anna play today?',NULL,'["She is sick.","She has homework.","She has a piano lesson.","It is raining."]',2,'Anna says she has a piano lesson today.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-ea9d08b69630','TOEFLJ','listening','mcq',1,'Tom: Hi, Anna. Do you want to play soccer after school?
