INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-a762907cf138','TOEFLJ','listening','mcq',2,'Hello, students. Our school library is closed on Wednesday. You can return your books on Thursday morning. On Friday, a writer will visit the library and read a new story to everyone.','When is the library closed?',NULL,'["Thursday","Wednesday","Monday","Friday"]',1,'The speaker says the library is closed on Wednesday.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-edcb10a37be8','TOEFLJ','listening','mcq',2,'Hello, students. Our school library is closed on Wednesday. You can return your books on Thursday morning. On Friday, a writer will visit the library and read a new story to everyone.','What can students do on Thursday morning?',NULL,'["Buy books","Return books","Meet a writer","Write a story"]',1,'The speaker says students can return their books on Thursday morning.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-a814d0b8ee86','TOEFLJ','listening','mcq',2,'Hello, students. Our school library is closed on Wednesday. You can return your books on Thursday morning. On Friday, a writer will visit the library and read a new story to everyone.','Who will visit the library on Friday?',NULL,'["A singer","A writer","A teacher","A doctor"]',1,'The speaker says a writer will visit on Friday and read a story.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-05ed9066fe13','TOEFLJ','listening','mcq',1,'Ms. Kim: Ben, where is your hat?
