INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-9dcc2a3dc22a','TOEFLJ','listening','mcq',1,'Ms. Kim: Ben, where is your hat?
