INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-03fee313bb52','TOEFLJ','listening','mcq',2,'Mom: Lily, it''s time for breakfast. Do you want eggs or pancakes?
