INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-2c37c83786b8','TOEFLJ','listening','mcq',1,'Everyone, please stand up. Now, put your hands on your head. Good! Now touch your toes. Great job! Please sit down and be quiet.','What should the students do first?',NULL,'["Be quiet","Stand up","Sit down","Touch their toes"]',1,'The first thing the teacher says is "please stand up."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-a20a840e08d1','TOEFLJ','listening','mcq',1,'Everyone, please stand up. Now, put your hands on your head. Good! Now touch your toes. Great job! Please sit down and be quiet.','Where do the students put their hands?',NULL,'["On their head","On their desk","In their pockets","On their knees"]',0,'The teacher says to put their hands on their head.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-2abdb21f7396','TOEFLJ','listening','mcq',2,'Sam: Grandma, I made a card for your birthday.
