INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-dbba87eb8405','TOEFLJ','listening','mcq',2,'Sam: Grandma, I made a card for your birthday.
