INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-f4918e010d68','TOEFLJ','listening','mcq',2,'Good afternoon, everyone. It is raining outside, so we will not go to the playground today. Lunch break will be in the gym. Please walk, don''t run, in the hallway.','Why can''t the students go to the playground?',NULL,'["It is snowing.","It is raining.","It is closed.","It is too hot."]',1,'The speaker says it is raining outside.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-d731527bb92d','TOEFLJ','listening','mcq',2,'Good afternoon, everyone. It is raining outside, so we will not go to the playground today. Lunch break will be in the gym. Please walk, don''t run, in the hallway.','Where will lunch break be?',NULL,'["On the playground","In the classroom","In the gym","In the library"]',2,'The speaker says lunch break will be in the gym.',1,0);
