INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-b11e4c0c6bc2','TOEFLJ','listening','mcq',2,'Mr. Lopez: Class, tomorrow is our trip to the zoo. Please come to school at seven thirty. Bring a lunch and a water bottle. Don''t forget to wear comfortable shoes!','Where is the class going tomorrow?',NULL,'["To a farm","To the zoo","To a museum","To the beach"]',1,'Mr. Lopez says tomorrow is the trip to the zoo.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-5a142b8c20fb','TOEFLJ','listening','mcq',2,'Mr. Lopez: Class, tomorrow is our trip to the zoo. Please come to school at seven thirty. Bring a lunch and a water bottle. Don''t forget to wear comfortable shoes!','What time should the students come to school?',NULL,'["At eight","At seven","At eight thirty","At seven thirty"]',3,'Mr. Lopez says to come to school at seven thirty.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-236c63de54e9','TOEFLJ','listening','mcq',2,'Mr. Lopez: Class, tomorrow is our trip to the zoo. Please come to school at seven thirty. Bring a lunch and a water bottle. Don''t forget to wear comfortable shoes!','What should the students bring?',NULL,'["A lunch and a water bottle","A camera and a hat","Money and a map","A book and a pencil"]',0,'Mr. Lopez says to bring a lunch and a water bottle.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-0526777db875','TOEFLJ','lfm','mcq',1,NULL,'I have ___ apple in my bag.',NULL,'["a","an","two","many"]',1,'We use "an" before a word that starts with a vowel sound, like "apple."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-fedb9ec85373','TOEFLJ','lfm','mcq',1,NULL,'There are three ___ on the table.',NULL,'["cup","cups","a cup","cupes"]',1,'After "three" we need the plural noun "cups."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-45381d558c02','TOEFLJ','lfm','mcq',1,NULL,'She ___ ten years old.',NULL,'["am","is","are","be"]',1,'With "she" we use "is."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-b08f3cc8ae49','TOEFLJ','lfm','mcq',1,NULL,'The cat is ___ the box. You can''t see it because it is inside.',NULL,'["under","on","behind","in"]',3,'"Inside" the box means the cat is "in" the box.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-2ed6ff204e40','TOEFLJ','lfm','mcq',1,NULL,'Birds ___ fly, but fish cannot.',NULL,'["can","is","are","can''t"]',0,'"But fish cannot" shows the opposite, so birds "can" fly.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-810ba4d4d3c3','TOEFLJ','lfm','mcq',1,NULL,'This is my brother. ___ name is Leo.',NULL,'["Him","He","She","His"]',3,'"His" shows the name belongs to a boy.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-934eb0ad9303','TOEFLJ','lfm','mcq',1,NULL,'We go to school ___ Monday.',NULL,'["on","to","in","at"]',0,'We use "on" with days of the week.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-7e71e5ca766d','TOEFLJ','lfm','mcq',2,NULL,'Yesterday, I ___ my grandmother.',NULL,'["visit","visits","visited","visiting"]',2,'"Yesterday" means the past, so we use "visited."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-182b5b6a6619','TOEFLJ','lfm','mcq',1,NULL,'My brother and I ___ hungry.',NULL,'["am","be","is","are"]',3,'"My brother and I" means two people, so we use "are."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-9833f2a62c72','TOEFLJ','lfm','mcq',2,NULL,'There ___ some milk in the glass.',NULL,'["is","am","are","be"]',0,'"Milk" cannot be counted, so we say "there is."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-496e2163107b','TOEFLJ','lfm','mcq',2,NULL,'Look! The dog ___ under the tree right now.',NULL,'["is sleeping","sleeps","sleeping","sleep"]',0,'"Look!" and "right now" show an action happening now, so we use "is sleeping."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-d308e2b987d5','TOEFLJ','lfm','mcq',2,NULL,'Ken ___ breakfast every morning at seven.',NULL,'["are eating","eating","eat","eats"]',3,'For a habit with "Ken" (he), we add -s: "eats."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-583a06ba7984','TOEFLJ','lfm','mcq',1,NULL,'I wear a coat because it is ___ today.',NULL,'["happy","cold","hot","warm"]',1,'People wear coats when the weather is cold.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-f7e65717db84','TOEFLJ','lfm','mcq',2,NULL,'Please give the book to ___. I want to read it.',NULL,'["mine","my","me","I"]',2,'After "to" we use the object pronoun "me."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-72bbd596c3c6','TOEFLJ','lfm','mcq',2,NULL,'The movie starts ___ six o''clock.',NULL,'["on","in","for","at"]',3,'We use "at" with clock times.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-f87c6f881fd5','TOEFLJ','lfm','mcq',1,NULL,'A ___ has long ears and likes carrots.',NULL,'["fish","bird","snake","rabbit"]',3,'A rabbit has long ears and eats carrots.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-7a48ac4257ec','TOEFLJ','lfm','mcq',2,NULL,'How ___ pencils do you have?',NULL,'["old","many","much","long"]',1,'We use "how many" with nouns we can count, like "pencils."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-31aad59a0054','TOEFLJ','lfm','mcq',2,NULL,'Last summer we ___ to the beach.',NULL,'["went","going","go","goes"]',0,'"Last summer" is the past, and the past of "go" is "went."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-2f393e381afa','TOEFLJ','lfm','mcq',2,NULL,'Three ___ are playing in the park.',NULL,'["children","child","childs","childrens"]',0,'The plural of "child" is "children."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-87d4d7e2911c','TOEFLJ','lfm','mcq',1,NULL,'I brush my ___ every morning and night.',NULL,'["hands","teeth","feet","ears"]',1,'We brush our teeth in the morning and at night.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-789d88b8f822','TOEFLJ','lfm','mcq',2,NULL,'My sister doesn''t ___ coffee.',NULL,'["liked","like","likes","liking"]',1,'After "doesn''t" we use the base verb "like."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-080793d82958','TOEFLJ','lfm','mcq',2,NULL,'The ball is ___ the chair, so I can''t see it.',NULL,'["in front of","behind","on","next to"]',1,'If the ball is behind the chair, the chair hides it.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-f8197aa1ee35','TOEFLJ','lfm','mcq',1,NULL,'"Is this your bag?" "Yes, it ___."',NULL,'["does","am","is","are"]',2,'The short answer to "Is this...?" is "Yes, it is."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-ddecd3c2b469','TOEFLJ','lfm','mcq',2,NULL,'We were very tired, ___ we went to bed early.',NULL,'["or","so","because","but"]',1,'"So" shows the result: being tired made us go to bed early.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-d0e7dd7dfef8','TOEFLJ','reading','mcq',1,'LIBRARY RULES. Please be quiet. No food or drinks. Return books in two weeks. Open Monday to Friday, 9:00 to 4:00.','Where would you see this sign?',NULL,'["In a kitchen","In a pool","In a library","In a park"]',2,'The sign says "LIBRARY RULES."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-eb9a89ef1a4c','TOEFLJ','reading','mcq',1,'LIBRARY RULES. Please be quiet. No food or drinks. Return books in two weeks. Open Monday to Friday, 9:00 to 4:00.','What can''t you bring?',NULL,'["Books","Food","Paper","Pencils"]',1,'The sign says "No food or drinks."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-30466df6d53c','TOEFLJ','reading','mcq',1,'LIBRARY RULES. Please be quiet. No food or drinks. Return books in two weeks. Open Monday to Friday, 9:00 to 4:00.','When must you return books?',NULL,'["In one day","In one month","In one week","In two weeks"]',3,'The sign says to return books in two weeks.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-e9de1fd7b32e','TOEFLJ','reading','mcq',1,'Dear Mom, I am at Emma''s house. We are doing our math homework together. Her dad will drive me home at five o''clock. Love, Jenny','Who wrote the note?',NULL,'["Emma''s dad","Jenny","Mom","Emma"]',1,'The note ends with "Love, Jenny."',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-e59ea34beb35','TOEFLJ','reading','mcq',1,'Dear Mom, I am at Emma''s house. We are doing our math homework together. Her dad will drive me home at five o''clock. Love, Jenny','What are the girls doing?',NULL,'["Doing math homework","Cooking dinner","Watching TV","Playing outside"]',0,'Jenny writes that they are doing math homework together.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-99607b158b76','TOEFLJ','reading','mcq',1,'Dear Mom, I am at Emma''s house. We are doing our math homework together. Her dad will drive me home at five o''clock. Love, Jenny','How will Jenny get home?',NULL,'["She will take a bus.","Emma''s dad will drive her.","Mom will get her.","She will walk."]',1,'Jenny writes that Emma''s dad will drive her home.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-ff935393f192','TOEFLJ','reading','mcq',2,'Sunny Cafe Lunch Menu. Sandwich: three dollars. Bowl of soup: two dollars. Fruit cup: one dollar. Orange juice: two dollars. Every Friday, kids get a free cookie with lunch.','Which food costs the most?',NULL,'["Orange juice","Soup","Sandwich","Fruit cup"]',2,'The sandwich costs three dollars, more than anything else.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-9a18454d3030','TOEFLJ','reading','mcq',2,'Sunny Cafe Lunch Menu. Sandwich: three dollars. Bowl of soup: two dollars. Fruit cup: one dollar. Orange juice: two dollars. Every Friday, kids get a free cookie with lunch.','How much are a sandwich and a fruit cup together?',NULL,'["Two dollars","Four dollars","Three dollars","Five dollars"]',1,'Three dollars plus one dollar is four dollars.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-41ad88f92e0b','TOEFLJ','reading','mcq',2,'Sunny Cafe Lunch Menu. Sandwich: three dollars. Bowl of soup: two dollars. Fruit cup: one dollar. Orange juice: two dollars. Every Friday, kids get a free cookie with lunch.','What do kids get on Fridays?',NULL,'["A free sandwich","Free juice","Free soup","A free cookie"]',3,'The menu says kids get a free cookie every Friday.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-09895762e386','TOEFLJ','reading','mcq',2,'Leo has a small garden behind his house. In spring, he planted tomato seeds. Every morning, he gave them water. In summer, the plants grew tall and the tomatoes turned red. Leo picked them and made a salad for his family. Everyone said it was delicious.','Where is Leo''s garden?',NULL,'["Behind his house","At school","In front of his house","Next to the park"]',0,'The story says the garden is behind his house.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-8411bac2bbd6','TOEFLJ','reading','mcq',2,'Leo has a small garden behind his house. In spring, he planted tomato seeds. Every morning, he gave them water. In summer, the plants grew tall and the tomatoes turned red. Leo picked them and made a salad for his family. Everyone said it was delicious.','When did Leo plant the seeds?',NULL,'["In spring","In fall","In winter","In summer"]',0,'The story says he planted tomato seeds in spring.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-2a5a7f1dc5c6','TOEFLJ','reading','mcq',2,'Leo has a small garden behind his house. In spring, he planted tomato seeds. Every morning, he gave them water. In summer, the plants grew tall and the tomatoes turned red. Leo picked them and made a salad for his family. Everyone said it was delicious.','What did Leo do every morning?',NULL,'["He picked tomatoes.","He watered the plants.","He bought seeds.","He made a salad."]',1,'The story says he gave them water every morning.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-93120d765719','TOEFLJ','reading','mcq',2,'Leo has a small garden behind his house. In spring, he planted tomato seeds. Every morning, he gave them water. In summer, the plants grew tall and the tomatoes turned red. Leo picked them and made a salad for his family. Everyone said it was delicious.','What did his family think of the salad?',NULL,'["It tasted very good.","It was cold.","It was strange.","It was too big."]',0,'Everyone said the salad was delicious, which means it tasted very good.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-2270b3969e48','TOEFLJ','reading','mcq',2,'Dear Sam, Greetings from the mountains! The weather is cool and sunny. Yesterday, my family went hiking and we saw a deer near the lake. Tomorrow we will ride horses. I miss you! See you next week. Your friend, Nora','Where is Nora now?',NULL,'["At the beach","In a city","In the mountains","At home"]',2,'Nora writes "Greetings from the mountains!"',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-30ad158d06c4','TOEFLJ','reading','mcq',2,'Dear Sam, Greetings from the mountains! The weather is cool and sunny. Yesterday, my family went hiking and we saw a deer near the lake. Tomorrow we will ride horses. I miss you! See you next week. Your friend, Nora','What did Nora see yesterday?',NULL,'["A fox","A horse","A deer","A bear"]',2,'Nora writes that they saw a deer near the lake.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a35a01b729f1','TOEFLJ','reading','mcq',2,'Dear Sam, Greetings from the mountains! The weather is cool and sunny. Yesterday, my family went hiking and we saw a deer near the lake. Tomorrow we will ride horses. I miss you! See you next week. Your friend, Nora','What will Nora do tomorrow?',NULL,'["Go swimming","Go hiking","Ride horses","Go home"]',2,'Nora writes "Tomorrow we will ride horses." (They went hiking yesterday.)',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-45994a5a5632','TOEFLJ','reading','mcq',2,'Dear Sam, Greetings from the mountains! The weather is cool and sunny. Yesterday, my family went hiking and we saw a deer near the lake. Tomorrow we will ride horses. I miss you! See you next week. Your friend, Nora','How is the weather?',NULL,'["Hot and rainy","Cool and sunny","Cold and snowy","Warm and windy"]',1,'Nora writes that the weather is cool and sunny.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-1085d3708569','TOEFLJ','reading','mcq',1,'My name is Hana. I am nine years old. I have one sister and one brother. My sister is older than me. My brother is a baby. I like to draw pictures of animals.','How old is Hana?',NULL,'["Nine","Eight","Ten","Seven"]',0,'Hana says she is nine years old.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-bada60290b0f','TOEFLJ','reading','mcq',1,'My name is Hana. I am nine years old. I have one sister and one brother. My sister is older than me. My brother is a baby. I like to draw pictures of animals.','How many brothers does Hana have?',NULL,'["Two","Three","One","None"]',2,'Hana says she has one sister and one brother.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-37fcd8f69c3d','TOEFLJ','reading','mcq',1,'My name is Hana. I am nine years old. I have one sister and one brother. My sister is older than me. My brother is a baby. I like to draw pictures of animals.','Who is the youngest?',NULL,'["Hana","Her brother","Her friend","Her sister"]',1,'Hana''s brother is a baby, so he is the youngest.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-f2ce9ec2e314','TOEFLJ','reading','mcq',1,'My name is Hana. I am nine years old. I have one sister and one brother. My sister is older than me. My brother is a baby. I like to draw pictures of animals.','What does Hana like to draw?',NULL,'["Animals","Cars","Flowers","Houses"]',0,'Hana says she likes to draw pictures of animals.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-1c5139e363c7','TOEFLJ','reading','mcq',1,'SWIMMING POOL. Open every day from 10:00 to 6:00. Children under eight must swim with an adult. Please take a shower before you swim. No running!','When does the pool close?',NULL,'["At 4:00","At 10:00","At 6:00","At 8:00"]',2,'The pool is open from 10:00 to 6:00, so it closes at 6:00.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a7b0cf65c6ba','TOEFLJ','reading','mcq',1,'SWIMMING POOL. Open every day from 10:00 to 6:00. Children under eight must swim with an adult. Please take a shower before you swim. No running!','Who must swim with an adult?',NULL,'["Children under eight","Teachers","Children over eight","All children"]',0,'The sign says children under eight must swim with an adult.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-d6f5206ab2d4','TOEFLJ','reading','mcq',1,'SWIMMING POOL. Open every day from 10:00 to 6:00. Children under eight must swim with an adult. Please take a shower before you swim. No running!','What should you do before you swim?',NULL,'["Eat lunch","Buy a ticket","Take a shower","Run around"]',2,'The sign says to take a shower before you swim.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-2810c6117855','TOEFLJ','reading','mcq',2,'On Saturday, Max lost his red ball in the park. He looked under the benches and behind the trees, but he could not find it. Then he saw a small dog. The dog had the ball in its mouth! The dog dropped the ball, and Max threw it for the dog to catch.','What did Max lose?',NULL,'["His dog","His red ball","His hat","His bike"]',1,'The story says Max lost his red ball in the park.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-f92dad0cc228','TOEFLJ','reading','mcq',2,'On Saturday, Max lost his red ball in the park. He looked under the benches and behind the trees, but he could not find it. Then he saw a small dog. The dog had the ball in its mouth! The dog dropped the ball, and Max threw it for the dog to catch.','Who had the ball?',NULL,'["A small dog","A boy","A cat","A bird"]',0,'The small dog had the ball in its mouth.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a7b4ce75e995','TOEFLJ','reading','mcq',2,'On Saturday, Max lost his red ball in the park. He looked under the benches and behind the trees, but he could not find it. Then he saw a small dog. The dog had the ball in its mouth! The dog dropped the ball, and Max threw it for the dog to catch.','What did Max do at the end?',NULL,'["He went home.","He threw the ball for the dog.","He cried.","He took the dog home."]',1,'At the end, Max threw the ball for the dog to catch.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-5475b6e0126e','TOEFLJ','listening','mcq',1,'Mia: Excuse me, Mr. Lee. I think I left my science notebook in your classroom.
Mr. Lee: Let me look. Is it the blue one with a star on the cover?
Mia: Yes! That''s it.
Mr. Lee: I found it on a desk by the window after third period. Here you go.
Mia: Thank you so much. I need it for my homework tonight.
Mr. Lee: You''re welcome. Next time, put it in your bag before you leave.','Why does Mia talk to Mr. Lee?',NULL,'["To ask about a notebook she lost","To show him her science project","To borrow a blue pen","To ask for extra homework"]',0,'Mia says she left her notebook in his classroom.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-bea279c54d3d','TOEFLJ','listening','mcq',1,'Mia: Excuse me, Mr. Lee. I think I left my science notebook in your classroom.
Mr. Lee: Let me look. Is it the blue one with a star on the cover?
Mia: Yes! That''s it.
Mr. Lee: I found it on a desk by the window after third period. Here you go.
Mia: Thank you so much. I need it for my homework tonight.
Mr. Lee: You''re welcome. Next time, put it in your bag before you leave.','Where did Mr. Lee find the notebook?',NULL,'["Under his chair","In the library","On a desk by the window","In Mia''s bag"]',2,'He says he found it on a desk by the window.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-67a35f70a81b','TOEFLJ','listening','mcq',2,'Mia: Excuse me, Mr. Lee. I think I left my science notebook in your classroom.
Mr. Lee: Let me look. Is it the blue one with a star on the cover?
Mia: Yes! That''s it.
Mr. Lee: I found it on a desk by the window after third period. Here you go.
Mia: Thank you so much. I need it for my homework tonight.
Mr. Lee: You''re welcome. Next time, put it in your bag before you leave.','What does Mr. Lee suggest?',NULL,'["Buying a new notebook","Doing her homework in class","Writing her name on the cover","Putting the notebook in her bag before leaving"]',3,'He advises her to put it in her bag before she leaves.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-74c65f9a9b91','TOEFLJ','listening','mcq',1,'Attention, students. The Spring Book Fair begins on Monday in the library. It will be open every day from eight to four until Friday. This year, there will be a special table with books written by students in our school. Each class will visit the fair once, but you may also come before school or at lunch. Remember to bring money in an envelope with your name on it. Half of the money we earn will buy new books for our library.','What is the main purpose of the announcement?',NULL,'["To change the school schedule","To ask students to return library books","To announce a writing contest","To tell students about a book fair"]',3,'The speaker introduces the Spring Book Fair and gives details.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-b1fe0e85be2c','TOEFLJ','listening','mcq',2,'Attention, students. The Spring Book Fair begins on Monday in the library. It will be open every day from eight to four until Friday. This year, there will be a special table with books written by students in our school. Each class will visit the fair once, but you may also come before school or at lunch. Remember to bring money in an envelope with your name on it. Half of the money we earn will buy new books for our library.','What should students bring to the fair?',NULL,'["A note from a parent","A book to sell","A library card","Money in an envelope with their name"]',3,'The speaker says to bring money in an envelope with your name on it.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-a3b8518ae92e','TOEFLJ','listening','mcq',2,'Attention, students. The Spring Book Fair begins on Monday in the library. It will be open every day from eight to four until Friday. This year, there will be a special table with books written by students in our school. Each class will visit the fair once, but you may also come before school or at lunch. Remember to bring money in an envelope with your name on it. Half of the money we earn will buy new books for our library.','What will happen to half of the money the fair earns?',NULL,'["It will be used to buy library books","It will go to the students who wrote books","It will be given to teachers","It will pay for a school trip"]',0,'The speaker says half will buy new books for the library.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-bff6110d1d9a','TOEFLJ','listening','mcq',2,'Today we are going to talk about how honeybees communicate. When a bee finds a good field of flowers, it returns to the hive and does a special movement called the waggle dance. The direction of the dance shows where the flowers are compared with the sun. The longer the bee waggles, the farther away the flowers are. Scientists were surprised to learn this, because bees have very small brains. Other bees watch the dance in the dark hive and then fly straight to the flowers.','What is the talk mainly about?',NULL,'["Why bees make honey","How bees build a hive","Which flowers bees like best","How honeybees tell others where flowers are"]',3,'The talk explains the waggle dance that shows flower locations.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-dafc0438d6b0','TOEFLJ','listening','mcq',3,'Today we are going to talk about how honeybees communicate. When a bee finds a good field of flowers, it returns to the hive and does a special movement called the waggle dance. The direction of the dance shows where the flowers are compared with the sun. The longer the bee waggles, the farther away the flowers are. Scientists were surprised to learn this, because bees have very small brains. Other bees watch the dance in the dark hive and then fly straight to the flowers.','What does a longer waggle show?',NULL,'["The flowers are bigger","The sun is higher","There are more bees","The flowers are farther away"]',3,'The speaker says the longer the bee waggles, the farther away the flowers are.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-e69379b030e7','TOEFLJ','listening','mcq',3,'Today we are going to talk about how honeybees communicate. When a bee finds a good field of flowers, it returns to the hive and does a special movement called the waggle dance. The direction of the dance shows where the flowers are compared with the sun. The longer the bee waggles, the farther away the flowers are. Scientists were surprised to learn this, because bees have very small brains. Other bees watch the dance in the dark hive and then fly straight to the flowers.','Why were scientists surprised by the waggle dance?',NULL,'["Bees live alone","Bees cannot see the sun","Bees have very small brains","Bees dance only at night"]',2,'The speaker says this was surprising because bees have very small brains.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-fd04528887bd','TOEFLJ','listening','mcq',2,'Ben: Have you decided what we should build for the science fair?
Lena: I was thinking about a volcano, but everyone does that.
Ben: True. Last year, five groups made volcanoes.
Lena: What about a small water filter? We could show how dirty water becomes cleaner.
Ben: That''s a great idea, but it might take a lot of materials.
Lena: Not really. We only need sand, small stones, cotton, and a plastic bottle.
Ben: Okay, I''m in. I''ll bring the bottle tomorrow.','Why does Lena not want to build a volcano?',NULL,'["It costs too much","It is too difficult","Too many people already make one","The teacher does not like it"]',2,'She says everyone does that, and Ben mentions five groups last year.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-bd29c81eb2e6','TOEFLJ','listening','mcq',3,'Ben: Have you decided what we should build for the science fair?
Lena: I was thinking about a volcano, but everyone does that.
Ben: True. Last year, five groups made volcanoes.
Lena: What about a small water filter? We could show how dirty water becomes cleaner.
Ben: That''s a great idea, but it might take a lot of materials.
Lena: Not really. We only need sand, small stones, cotton, and a plastic bottle.
Ben: Okay, I''m in. I''ll bring the bottle tomorrow.','What is Ben worried about when he hears the water filter idea?',NULL,'["It may need a lot of materials","It may take too much time to explain","It may be too dirty","It may not work"]',0,'Ben says it might take a lot of materials.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-533874b8c627','TOEFLJ','listening','mcq',2,'Ben: Have you decided what we should build for the science fair?
Lena: I was thinking about a volcano, but everyone does that.
Ben: True. Last year, five groups made volcanoes.
Lena: What about a small water filter? We could show how dirty water becomes cleaner.
Ben: That''s a great idea, but it might take a lot of materials.
Lena: Not really. We only need sand, small stones, cotton, and a plastic bottle.
Ben: Okay, I''m in. I''ll bring the bottle tomorrow.','What will Ben do next?',NULL,'["Ask the teacher","Buy some sand","Bring a plastic bottle","Draw a plan"]',2,'He says he will bring the bottle tomorrow.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-d43c1ba7e27e','TOEFLJ','listening','mcq',1,'Good morning, everyone. This is Ms. Garcia with an important change. Because of the heavy rain forecast for Thursday, the sixth-grade trip to the city zoo has been moved to next Tuesday. Buses will still leave at nine o''clock. If you have already returned your permission form, you do not need to send another one. Students who cannot go on Tuesday should speak to their homeroom teacher today. On Thursday, sixth graders will have regular classes.','What is the announcement mostly about?',NULL,'["A change in the date of a trip","A zoo animal show","A rainy-day class","A new bus schedule"]',0,'The zoo trip was moved from Thursday to Tuesday.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-9abc79a51bd6','TOEFLJ','listening','mcq',1,'Good morning, everyone. This is Ms. Garcia with an important change. Because of the heavy rain forecast for Thursday, the sixth-grade trip to the city zoo has been moved to next Tuesday. Buses will still leave at nine o''clock. If you have already returned your permission form, you do not need to send another one. Students who cannot go on Tuesday should speak to their homeroom teacher today. On Thursday, sixth graders will have regular classes.','Why was the trip moved?',NULL,'["Many students are sick","Heavy rain is expected on Thursday","The buses are broken","The zoo is closed"]',1,'The speaker mentions the heavy rain forecast for Thursday.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-5e5fb411484e','TOEFLJ','listening','mcq',2,'Good morning, everyone. This is Ms. Garcia with an important change. Because of the heavy rain forecast for Thursday, the sixth-grade trip to the city zoo has been moved to next Tuesday. Buses will still leave at nine o''clock. If you have already returned your permission form, you do not need to send another one. Students who cannot go on Tuesday should speak to their homeroom teacher today. On Thursday, sixth graders will have regular classes.','What should students who cannot go on Tuesday do?',NULL,'["Go to the zoo on Thursday","Call the zoo","Send another permission form","Talk to their homeroom teacher"]',3,'The speaker tells them to speak to their homeroom teacher today.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-db0ad6efabfa','TOEFLJ','listening','mcq',3,'The Silk Road was not one single road. It was a network of trade routes that connected China with lands as far away as Italy. Merchants rarely traveled the whole distance. Instead, goods passed from trader to trader, and each one added a little to the price. Silk was famous, but travelers also carried spices, glass, and paper. Perhaps more important than any product, ideas moved along these routes too. Religions, stories, and new technologies spread slowly from town to town, changing the places they reached.','What is the main point of the talk?',NULL,'["Silk was the only product traded","Merchants traveled from China to Italy in one trip","The Silk Road was a network that spread both goods and ideas","The Silk Road was a single straight road"]',2,'The speaker describes a network of routes carrying goods and ideas.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-543be1baf837','TOEFLJ','listening','mcq',3,'The Silk Road was not one single road. It was a network of trade routes that connected China with lands as far away as Italy. Merchants rarely traveled the whole distance. Instead, goods passed from trader to trader, and each one added a little to the price. Silk was famous, but travelers also carried spices, glass, and paper. Perhaps more important than any product, ideas moved along these routes too. Religions, stories, and new technologies spread slowly from town to town, changing the places they reached.','Why did goods become more expensive along the routes?',NULL,'["Silk was hard to make","Each trader added something to the price","Roads were very dangerous","Taxes were very high"]',1,'The speaker says each trader added a little to the price.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-6555d3c3d765','TOEFLJ','listening','mcq',4,'The Silk Road was not one single road. It was a network of trade routes that connected China with lands as far away as Italy. Merchants rarely traveled the whole distance. Instead, goods passed from trader to trader, and each one added a little to the price. Silk was famous, but travelers also carried spices, glass, and paper. Perhaps more important than any product, ideas moved along these routes too. Religions, stories, and new technologies spread slowly from town to town, changing the places they reached.','What does the speaker suggest about ideas on the Silk Road?',NULL,'["They were less important than silk","They moved faster than goods","They were mostly lost","They may have mattered more than the products"]',3,'She says that perhaps ideas were more important than any product.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-491b42082232','TOEFLJ','listening','mcq',2,'Ms. Park: Daniel, your painting of the harbor is lovely. I especially like the colors in the sky.
Daniel: Thanks, but I''m not happy with the boats. They look flat.
Ms. Park: I see what you mean. Try adding a few darker lines under each boat to show shadows.
Daniel: Oh, so they''ll look like they''re sitting on the water?
Ms. Park: Exactly. And don''t worry. Even professional artists spend hours fixing small details.
Daniel: That makes me feel better. I''ll try it after lunch.','What problem does Daniel have with his painting?',NULL,'["The sky is too dark","The boats look flat","The harbor is too small","He ran out of paint"]',1,'Daniel says the boats look flat.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-6c608305793f','TOEFLJ','listening','mcq',3,'Ms. Park: Daniel, your painting of the harbor is lovely. I especially like the colors in the sky.
Daniel: Thanks, but I''m not happy with the boats. They look flat.
Ms. Park: I see what you mean. Try adding a few darker lines under each boat to show shadows.
Daniel: Oh, so they''ll look like they''re sitting on the water?
Ms. Park: Exactly. And don''t worry. Even professional artists spend hours fixing small details.
Daniel: That makes me feel better. I''ll try it after lunch.','What does Ms. Park suggest Daniel do?',NULL,'["Add darker lines to show shadows","Make the boats larger","Start a new painting","Paint the sky again"]',0,'She tells him to add darker lines under each boat.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-0ef91ea151e7','TOEFLJ','listening','mcq',4,'Ms. Park: Daniel, your painting of the harbor is lovely. I especially like the colors in the sky.
Daniel: Thanks, but I''m not happy with the boats. They look flat.
Ms. Park: I see what you mean. Try adding a few darker lines under each boat to show shadows.
Daniel: Oh, so they''ll look like they''re sitting on the water?
Ms. Park: Exactly. And don''t worry. Even professional artists spend hours fixing small details.
Daniel: That makes me feel better. I''ll try it after lunch.','Why does Ms. Park mention professional artists?',NULL,'["To help Daniel feel less worried","To compare his painting with theirs","To show Daniel''s work is bad","To tell him to practice more at home"]',0,'Her comment makes Daniel feel better, so it is meant to reassure him.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-803708490511','TOEFLJ','listening','mcq',3,'Many people think that a volcano is simply a mountain that throws out fire. In fact, a volcano is an opening in the Earth''s crust where hot melted rock, called magma, can escape. When magma reaches the surface, we call it lava. Some volcanoes erupt gently, and lava slowly flows down the sides. Others explode violently because gas is trapped inside the magma, much like the bubbles in a soda bottle that has been shaken. That is why scientists study the gas levels before they predict an eruption.','What is the talk mainly about?',NULL,'["What a volcano is and why eruptions differ","Where most volcanoes are found","Why mountains are tall","How to stay safe near lava"]',0,'The speaker defines volcanoes and explains gentle and explosive eruptions.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-2875554afdfe','TOEFLJ','listening','mcq',3,'Many people think that a volcano is simply a mountain that throws out fire. In fact, a volcano is an opening in the Earth''s crust where hot melted rock, called magma, can escape. When magma reaches the surface, we call it lava. Some volcanoes erupt gently, and lava slowly flows down the sides. Others explode violently because gas is trapped inside the magma, much like the bubbles in a soda bottle that has been shaken. That is why scientists study the gas levels before they predict an eruption.','According to the speaker, why do some volcanoes explode?',NULL,'["The lava is cold","Rain falls into the opening","Gas is trapped in the magma","The mountain is very tall"]',2,'The speaker says gas trapped inside magma causes violent eruptions.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-194670405c67','TOEFLJ','listening','mcq',4,'Many people think that a volcano is simply a mountain that throws out fire. In fact, a volcano is an opening in the Earth''s crust where hot melted rock, called magma, can escape. When magma reaches the surface, we call it lava. Some volcanoes erupt gently, and lava slowly flows down the sides. Others explode violently because gas is trapped inside the magma, much like the bubbles in a soda bottle that has been shaken. That is why scientists study the gas levels before they predict an eruption.','Why does the speaker mention a shaken soda bottle?',NULL,'["To describe how scientists work","To explain why lava is hot","To help listeners picture how trapped gas builds pressure","To show that volcanoes are small"]',2,'The comparison makes the idea of trapped gas easier to imagine.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-5f796c115891','TOEFLJ','listening','mcq',2,'Sara: Are you going to the soccer tryouts on Friday?
Tom: I want to, but I''m nervous. I hurt my ankle last month.
Sara: Does it still hurt?
Tom: Not really, but the doctor told me to take it easy.
Sara: Maybe you should ask her if you can play.
Tom: You''re right. I have an appointment on Wednesday. I''ll ask then.
Sara: Good idea. Whatever happens, I''ll cheer for you.','Why is Tom nervous about the tryouts?',NULL,'["He does not know the coach","He hurt his ankle","He has never played soccer","He has a test on Friday"]',1,'Tom says he hurt his ankle last month.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-62186e718993','TOEFLJ','listening','mcq',3,'Sara: Are you going to the soccer tryouts on Friday?
Tom: I want to, but I''m nervous. I hurt my ankle last month.
Sara: Does it still hurt?
Tom: Not really, but the doctor told me to take it easy.
Sara: Maybe you should ask her if you can play.
Tom: You''re right. I have an appointment on Wednesday. I''ll ask then.
Sara: Good idea. Whatever happens, I''ll cheer for you.','What will Tom probably do before deciding to try out?',NULL,'["Ask the coach on Friday","Skip the tryouts","Practice with Sara","Ask his doctor on Wednesday"]',3,'He says he has an appointment Wednesday and will ask then.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-437aee07d931','TOEFLJ','listening','mcq',2,'Hello, students. Starting next week, our cafeteria will use new recycling bins. There will be three colors. Blue bins are for paper and cardboard, green bins are for plastic bottles and cans, and black bins are for food waste. Last month, we found that nearly half of the items in the trash could have been recycled. Student volunteers from the Green Club will stand near the bins for the first two weeks to help. If you would like to join them, please see Mr. Adams in Room 12.','What will the green bins be used for?',NULL,'["Paper and cardboard","Glass jars","Plastic bottles and cans","Food waste"]',2,'Green bins are for plastic bottles and cans.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-780aaa592137','TOEFLJ','listening','mcq',3,'Hello, students. Starting next week, our cafeteria will use new recycling bins. There will be three colors. Blue bins are for paper and cardboard, green bins are for plastic bottles and cans, and black bins are for food waste. Last month, we found that nearly half of the items in the trash could have been recycled. Student volunteers from the Green Club will stand near the bins for the first two weeks to help. If you would like to join them, please see Mr. Adams in Room 12.','Why is the school making this change?',NULL,'["Students asked for colorful bins","The cafeteria is too dirty","Too many recyclable items are going in the trash","The old bins were broken"]',2,'The speaker says nearly half the trash could have been recycled.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-5896738a2268','TOEFLJ','listening','mcq',3,'Bats fly at night, when it is too dark to see well, so many of them use sound instead of light. A bat makes a high squeak that people cannot hear. The sound travels until it hits an object, such as a moth, and then bounces back. The bat listens to the returning sound, the echo, and can tell how big the object is and how far away it is. This ability is called echolocation. Interestingly, not every bat relies on it. Some fruit bats have large eyes and see quite well.','How does a bat learn where a moth is?',NULL,'["By seeing it in the dark","By listening to the echo of its own squeak","By smelling it","By feeling the wind it makes"]',1,'The speaker explains that the bat hears the echo of its squeak.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-a44bb4bc8d68','TOEFLJ','listening','mcq',4,'Bats fly at night, when it is too dark to see well, so many of them use sound instead of light. A bat makes a high squeak that people cannot hear. The sound travels until it hits an object, such as a moth, and then bounces back. The bat listens to the returning sound, the echo, and can tell how big the object is and how far away it is. This ability is called echolocation. Interestingly, not every bat relies on it. Some fruit bats have large eyes and see quite well.','What does the speaker imply about fruit bats?',NULL,'["They fly only in daylight","They are larger than other bats","They cannot hear any sounds","Some rely less on echolocation because they see well"]',3,'The speaker says some have large eyes and see well, so not every bat relies on echolocation.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-ff77ef4c3bb9','TOEFLJ','listening','mcq',2,'Mr. Rossi: Chloe, I noticed your history essay wasn''t on my desk this morning.
Chloe: I''m sorry, Mr. Rossi. I finished it, but my printer stopped working last night.
Mr. Rossi: I understand that technology can be unreliable. Could you email it to me before lunch?
Chloe: Yes, I can do that right now from the library.
Mr. Rossi: Fine. I''ll accept it without a penalty this time, but please plan ahead in the future.
Chloe: I will. Thank you for being understanding.','Why was Chloe''s essay late?',NULL,'["She forgot to write it","She was absent from school","She lost her notebook","Her printer stopped working"]',3,'Chloe says her printer stopped working last night.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-db3108b586a7','TOEFLJ','listening','mcq',3,'Mr. Rossi: Chloe, I noticed your history essay wasn''t on my desk this morning.
Chloe: I''m sorry, Mr. Rossi. I finished it, but my printer stopped working last night.
Mr. Rossi: I understand that technology can be unreliable. Could you email it to me before lunch?
Chloe: Yes, I can do that right now from the library.
Mr. Rossi: Fine. I''ll accept it without a penalty this time, but please plan ahead in the future.
Chloe: I will. Thank you for being understanding.','What will Chloe do next?',NULL,'["Print it at home","Give it to Mr. Rossi tomorrow","Rewrite it after lunch","Email the essay from the library"]',3,'She says she can email it right now from the library.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-e59dc2e85324','TOEFLJ','listening','mcq',4,'Mr. Rossi: Chloe, I noticed your history essay wasn''t on my desk this morning.
Chloe: I''m sorry, Mr. Rossi. I finished it, but my printer stopped working last night.
Mr. Rossi: I understand that technology can be unreliable. Could you email it to me before lunch?
Chloe: Yes, I can do that right now from the library.
Mr. Rossi: Fine. I''ll accept it without a penalty this time, but please plan ahead in the future.
Chloe: I will. Thank you for being understanding.','What is Mr. Rossi''s attitude toward Chloe?',NULL,'["Doubtful that she finished it","Understanding, but he wants her to plan better","Angry about the late essay","Happy to accept late work every time"]',1,'He accepts it without a penalty but asks her to plan ahead.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-fc32112b3470','TOEFLJ','listening','mcq',3,'In the 1870s, a group of French painters decided to leave their studios and paint outdoors. Critics laughed at them. One critic looked at a painting by Claude Monet called Impression, Sunrise and mocked the whole group by calling them Impressionists, because their work seemed unfinished to him. Instead of hiding a loose brushstroke, these painters used it on purpose to capture how light changes during a day. The insulting name stuck, and the artists eventually adopted it proudly. Today, their paintings are among the most beloved in the world.','What is the talk mainly about?',NULL,'["Why Monet moved to a studio","How to paint outdoors","How Impressionism got its name","Why critics enjoy art"]',2,'The speaker explains that a critic mocked the group with the name Impressionists.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-6e5c651fbe1b','TOEFLJ','listening','mcq',4,'In the 1870s, a group of French painters decided to leave their studios and paint outdoors. Critics laughed at them. One critic looked at a painting by Claude Monet called Impression, Sunrise and mocked the whole group by calling them Impressionists, because their work seemed unfinished to him. Instead of hiding a loose brushstroke, these painters used it on purpose to capture how light changes during a day. The insulting name stuck, and the artists eventually adopted it proudly. Today, their paintings are among the most beloved in the world.','Why did the critic use the word Impressionists?',NULL,'["To describe a new school","To praise their bright colors","To make fun of the painters","To honor Monet"]',2,'The speaker says he mocked the group because their work seemed unfinished.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-c823383fc8eb','TOEFLJ','listening','mcq',5,'In the 1870s, a group of French painters decided to leave their studios and paint outdoors. Critics laughed at them. One critic looked at a painting by Claude Monet called Impression, Sunrise and mocked the whole group by calling them Impressionists, because their work seemed unfinished to him. Instead of hiding a loose brushstroke, these painters used it on purpose to capture how light changes during a day. The insulting name stuck, and the artists eventually adopted it proudly. Today, their paintings are among the most beloved in the world.','What can be inferred about the painters'' reaction to the name?',NULL,'["They stopped painting outdoors","They refused to use it","They came to accept it despite its origin","They asked the critic to explain it"]',2,'The speaker says they eventually adopted the insulting name proudly.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-ea5e616b1360','TOEFLJ','listening','mcq',1,'Hi, everyone. The drama club is holding auditions for this year''s school play, The Magic Garden, next Wednesday after school in the auditorium. You do not need any acting experience. Just prepare a one-minute reading from any book you like. There are twelve parts, and we also need students to help with costumes and lights. Sign-up sheets are outside the music room. Don''t be shy. It''s a lot of fun!','What is the announcement about?',NULL,'["A costume sale","A book club meeting","Music lessons","Auditions for a school play"]',3,'The drama club is holding auditions for The Magic Garden.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-listening-9eff3f564c09','TOEFLJ','listening','mcq',2,'Hi, everyone. The drama club is holding auditions for this year''s school play, The Magic Garden, next Wednesday after school in the auditorium. You do not need any acting experience. Just prepare a one-minute reading from any book you like. There are twelve parts, and we also need students to help with costumes and lights. Sign-up sheets are outside the music room. Don''t be shy. It''s a lot of fun!','What do students need to prepare?',NULL,'["A written story","A costume","A one-minute reading","A short song"]',2,'The speaker says to prepare a one-minute reading from any book.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-93e5ad7efc33','TOEFLJ','lfm','mcq',1,NULL,'My sister ___ a student at this school.',NULL,'["be","are","is","am"]',2,'A singular subject takes is.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-325ffcd69278','TOEFLJ','lfm','mcq',1,NULL,'We ___ pizza for lunch yesterday.',NULL,'["ate","eating","eat","eaten"]',0,'Yesterday needs the simple past ate.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-559408c9d59f','TOEFLJ','lfm','mcq',1,NULL,'There is ___ apple on the table.',NULL,'["a","an","some","many"]',1,'Apple begins with a vowel sound and is singular, so an is used.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-21c598a49347','TOEFLJ','lfm','mcq',1,NULL,'She goes to school ___ bus.',NULL,'["at","in","by","with"]',2,'We say by bus for a means of transport.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-3cc876fe45b8','TOEFLJ','lfm','mcq',2,NULL,'I was reading when the phone ___.',NULL,'["ringing","rings","rang","has ring"]',2,'A short past action interrupts the ongoing action, so the simple past rang fits.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-77c83f91a3d3','TOEFLJ','lfm','mcq',2,NULL,'This puzzle is ___ than that one.',NULL,'["more easy","easiest","most easy","easier"]',3,'Short adjectives like easy form comparatives with -er.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-7023ac97398c','TOEFLJ','lfm','mcq',2,NULL,'You ___ wear a helmet when you ride a bike. It is the rule.',NULL,'["must","might","would","could"]',0,'Must expresses a rule or obligation.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-cd1b240e8f5c','TOEFLJ','lfm','mcq',2,NULL,'The girl ___ lives next door plays the violin.',NULL,'["which","who","whom","whose"]',1,'Who is the subject relative pronoun for a person.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-3ca2c94211d2','TOEFLJ','lfm','mcq',2,NULL,'I stayed home ___ it was raining.',NULL,'["although","but","because","or"]',2,'Because gives the reason for staying home.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-3219fcbbd140','TOEFLJ','lfm','mcq',2,NULL,'He is a very ___ boy; he always helps other people.',NULL,'["kind","kindly","kinder","kindness"]',0,'An adjective is needed to describe the noun boy.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-402e432fbaaa','TOEFLJ','lfm','mcq',3,NULL,'If it ___ tomorrow, we will cancel the picnic.',NULL,'["rained","would rain","will rain","rains"]',3,'In a first conditional, the if clause uses the present simple.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-68dcace0148b','TOEFLJ','lfm','mcq',3,NULL,'By the time we arrived, the movie ___.',NULL,'["is already starting","has already started","had already started","will already start"]',2,'By the time plus a past event needs the past perfect for the earlier action.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-15386b2f7027','TOEFLJ','lfm','mcq',3,NULL,'She is good ___ solving math problems.',NULL,'["at","in","for","on"]',0,'The adjective good takes the preposition at for skills.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-ba8fb4781b5d','TOEFLJ','lfm','mcq',3,NULL,'The museum, ___ opened in 1901, is free on Sundays.',NULL,'["what","who","which","where"]',2,'Which introduces a nonrestrictive clause about a thing.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-45c31cbf2a08','TOEFLJ','lfm','mcq',3,NULL,'I''m looking forward to ___ you next week.',NULL,'["saw","to see","see","seeing"]',3,'Look forward to is followed by an -ing form.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-2e9c26a6451e','TOEFLJ','lfm','mcq',3,NULL,'How ___ water do you drink every day?',NULL,'["lot","many","much","few"]',2,'Water is uncountable, so much is used.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-e11cb60a1e1f','TOEFLJ','lfm','mcq',3,NULL,'Please remember ___ the lights before you leave.',NULL,'["turned off","turn off","turning off","to turn off"]',3,'Remember to do means remember a task you must do.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-319b09f4f090','TOEFLJ','lfm','mcq',4,NULL,'Neither Tom nor his brothers ___ at home.',NULL,'["are","is","be","am"]',0,'With neither...nor, the verb agrees with the nearer subject, brothers.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-7cfbfb5e0a9c','TOEFLJ','lfm','mcq',4,NULL,'I wish I ___ more time to finish the project.',NULL,'["having","have","had","would have"]',2,'A wish about the present uses the past form had.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-f9590a7b11bc','TOEFLJ','lfm','mcq',4,NULL,'The book ___ by millions of people since it was published.',NULL,'["has read","is read","was reading","has been read"]',3,'Since with a passive meaning needs the present perfect passive.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-9c152dc547d0','TOEFLJ','lfm','mcq',4,NULL,'She asked me where ___.',NULL,'["do I buy the bag","I had bought the bag","did I buy the bag","had I bought the bag"]',1,'Reported questions use statement word order, with the verb shifted back.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-0623e4dd8163','TOEFLJ','lfm','mcq',4,NULL,'Not only ___ the test, but she also got the highest score.',NULL,'["passed she","she passed","did she pass","she did pass"]',2,'After Not only at the start, the auxiliary comes before the subject.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-24d55922f7c4','TOEFLJ','lfm','mcq',4,NULL,'The team was ___ after losing the final match.',NULL,'["disappointment","disappointing","disappointed","disappoint"]',2,'The participle -ed describes how the team felt.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-3c59e9e684fa','TOEFLJ','lfm','mcq',5,NULL,'Had I known about the traffic, I ___ earlier.',NULL,'["would leave","will leave","had left","would have left"]',3,'An inverted third conditional needs would have plus the past participle.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-8d82cefcc6a0','TOEFLJ','lfm','mcq',5,NULL,'The scientist, along with her assistants, ___ the results carefully.',NULL,'["have examined","are examining","were examining","is examining"]',3,'The subject is the singular scientist, so the verb is singular and present.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-9832f0b92fdd','TOEFLJ','lfm','mcq',5,NULL,'It is essential that every student ___ the form by Friday.',NULL,'["submit","submitted","submits","will submit"]',0,'After essential that, the subjunctive uses the base form.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-db58fa767af6','TOEFLJ','lfm','mcq',5,NULL,'The more you practice, ___ you will become.',NULL,'["the most confident","confident more","the more confident","more confident"]',2,'The more...the more uses the pattern the plus a comparative.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-d2d31e126930','TOEFLJ','lfm','mcq',5,NULL,'She would rather ___ at home than go to the party.',NULL,'["to stay","stay","staying","stayed"]',1,'Would rather is followed by the base verb.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-6a65cca0cc14','TOEFLJ','lfm','mcq',2,NULL,'The explorers were exhausted after climbing all day. In this sentence, exhausted means',NULL,'["very happy","very tired","lost","hungry"]',1,'Exhausted means extremely tired.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-486baa99a59d','TOEFLJ','lfm','mcq',3,NULL,'Our teacher gave us a brief summary of the story. In this sentence, brief means',NULL,'["funny","short","difficult","wrong"]',1,'A brief summary is a short one.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-e0c3b377ccc3','TOEFLJ','lfm','mcq',4,NULL,'Dana was reluctant to speak in front of the whole school. In this sentence, reluctant means',NULL,'["eager","able","unwilling","allowed"]',2,'Reluctant means not willing or not wanting to do something.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-7714129c6439','TOEFLJ','lfm','mcq',5,NULL,'The scientist''s explanation was so clear that even the youngest students could grasp the idea. In this sentence, grasp means',NULL,'["hold tightly","understand","copy","repeat"]',1,'Grasp an idea means to understand it.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-bd2d1a42535e','TOEFLJ','lfm','mcq',1,'Tom loves animals. He has two dogs and a cat. Every morning, he ___ them in the park before school.','Choose the best word or phrase to fill the blank.',NULL,'["walking","walk","walked","walks"]',3,'Every morning shows a habit, so the present simple walks fits.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-05ebe5cd7ecc','TOEFLJ','lfm','mcq',1,'It is Saturday morning. Lucy and her brother are at the market. They want to buy ___ vegetables for dinner tonight.','Choose the best word or phrase to fill the blank.',NULL,'["some","a","an","one"]',0,'Some is used with plural countable nouns in this positive sentence.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-0b13cfd007bb','TOEFLJ','lfm','mcq',2,'Last weekend, my family went to the beach. The water was cold, ___ we still swam for an hour. Afterwards, we ate sandwiches and built a big sandcastle.','Choose the best word or phrase to fill the blank.',NULL,'["because","but","if","so"]',1,'But shows contrast between cold water and swimming anyway.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-f82b2b3813f0','TOEFLJ','lfm','mcq',2,'Mei is a very busy student. She joins the choir and the chess club. ___, she still finds time to help her little brother with his reading.','Choose the best word or phrase to fill the blank.',NULL,'["For example","Finally","However","Because"]',2,'However marks the contrast between being busy and still finding time.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-3bb2e0816b5b','TOEFLJ','lfm','mcq',3,'The town library is changing. Next month it will open a new room for teenagers. The room will have comfortable chairs, fast computers, and a quiet corner ___ students can do homework.','Choose the best word or phrase to fill the blank.',NULL,'["who","where","which","what"]',1,'Where refers to a place in which an action happens.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-77788d42af21','TOEFLJ','lfm','mcq',3,'Nina has played the piano since she was six. She ___ in three competitions, and last year she won second prize. Now she is practicing for a bigger contest in the capital.','Choose the best word or phrase to fill the blank.',NULL,'["performs","is performing","has performed","will perform"]',2,'Her experience up to now calls for the present perfect.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-94bc55fa5955','TOEFLJ','lfm','mcq',4,'Many people believe that sharks are dangerous to humans. In reality, only a few species have ever attacked people, and most attacks are accidents. In fact, humans are a ___ greater threat to sharks than sharks are to us.','Choose the best word or phrase to fill the blank.',NULL,'["most","more","very","much"]',3,'Much can modify a comparative like greater, but very, more, and most cannot.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-4787f2c21e9a','TOEFLJ','lfm','mcq',4,'The village had no electricity until 1990. Before that, people ___ candles and oil lamps to light their homes at night. Today, solar panels cover many roofs.','Choose the best word or phrase to fill the blank.',NULL,'["used to using","were used to use","use to","used to use"]',3,'Used to plus base verb describes a past habit that no longer exists.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-9920cf9c2ba0','TOEFLJ','lfm','mcq',5,'The team spent six months testing the new fertilizer on bean plants. Although the experiment was expensive, the results were ___. Some plants grew taller, others did not change at all, so nobody could draw a firm conclusion.','Choose the best word or phrase to fill the blank.',NULL,'["concluded","conclusive","inclusion","inconclusive"]',3,'Results that do not allow a firm conclusion are inconclusive.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-lfm-909367d9fb01','TOEFLJ','lfm','mcq',5,'When Carlos moved to a new school, he felt lonely at first. ___ he joined the chess club, he began to make friends, and soon he looked forward to Mondays.','Choose the best word or phrase to fill the blank.',NULL,'["Whereas","Despite","Unless","Once"]',3,'Once means after the time that, linking joining the club to making friends.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-631fc7722067','TOEFLJ','reading','mcq',1,'Oakwood Middle School Library Club invites all students and families to the Spring Book Swap on Saturday, April 12, from 10:00 a.m. to 1:00 p.m. in the school gym. Bring up to five gently used books to trade. For each book you bring, you will receive one ticket, and each ticket can be exchanged for a different book on the day. Books that are torn or have missing pages cannot be accepted. Students who bring more than five books may donate the extras to the club, and the club will give them to the children''s hospital. Free lemonade will be served, and volunteers from the Library Club will be wearing yellow shirts to help you find books. No money is needed to attend. If you have questions, please email Ms. Alvarez at the library.','What is the main purpose of this notice?',NULL,'["To sell used books to raise money","To ask students to join a reading class","To announce that the library will close","To invite people to trade books at a school event"]',3,'The notice invites families to a book swap where books are traded.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-4f0bd8fbf295','TOEFLJ','reading','mcq',1,'Oakwood Middle School Library Club invites all students and families to the Spring Book Swap on Saturday, April 12, from 10:00 a.m. to 1:00 p.m. in the school gym. Bring up to five gently used books to trade. For each book you bring, you will receive one ticket, and each ticket can be exchanged for a different book on the day. Books that are torn or have missing pages cannot be accepted. Students who bring more than five books may donate the extras to the club, and the club will give them to the children''s hospital. Free lemonade will be served, and volunteers from the Library Club will be wearing yellow shirts to help you find books. No money is needed to attend. If you have questions, please email Ms. Alvarez at the library.','What will happen to books beyond the first five that a student brings?',NULL,'["They will be returned the next week","They will be traded for money","They will be thrown away","They may be donated to a children''s hospital"]',3,'Extras may be donated to the club, which gives them to the children''s hospital.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-093acae45f17','TOEFLJ','reading','mcq',2,'Oakwood Middle School Library Club invites all students and families to the Spring Book Swap on Saturday, April 12, from 10:00 a.m. to 1:00 p.m. in the school gym. Bring up to five gently used books to trade. For each book you bring, you will receive one ticket, and each ticket can be exchanged for a different book on the day. Books that are torn or have missing pages cannot be accepted. Students who bring more than five books may donate the extras to the club, and the club will give them to the children''s hospital. Free lemonade will be served, and volunteers from the Library Club will be wearing yellow shirts to help you find books. No money is needed to attend. If you have questions, please email Ms. Alvarez at the library.','In the notice, the words "gently used" most nearly mean',NULL,'["brand new and still in plastic","borrowed from the school library","very old and hard to read","in good condition after being read"]',3,'Gently used books have been read but are not badly damaged.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-93d1212e924f','TOEFLJ','reading','mcq',2,'Dear Parents, On Thursday, May 8, our fifth-grade classes will visit the Riverside Science Museum. Buses will leave the school at 8:30 a.m. and return by 3:00 p.m. Students should wear comfortable shoes and bring a bag lunch, since the museum cafe is closed for repairs. Please do not pack glass bottles or foods with peanuts, because several students have serious allergies. Each student must return the signed permission slip by Friday, May 2; students without one will stay at school and join another class. Parent volunteers are still needed. If you can join us, please reply to this message. We expect the day to be both fun and educational. Sincerely, Mr. Dawson','Why should students bring a bag lunch?',NULL,'["The school cafeteria is too far away.","The buses will not return until evening.","The museum cafe is closed for repairs.","Lunch is not allowed inside the museum."]',2,'The email says the cafe is closed for repairs.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-506f80e58987','TOEFLJ','reading','mcq',2,'Dear Parents, On Thursday, May 8, our fifth-grade classes will visit the Riverside Science Museum. Buses will leave the school at 8:30 a.m. and return by 3:00 p.m. Students should wear comfortable shoes and bring a bag lunch, since the museum cafe is closed for repairs. Please do not pack glass bottles or foods with peanuts, because several students have serious allergies. Each student must return the signed permission slip by Friday, May 2; students without one will stay at school and join another class. Parent volunteers are still needed. If you can join us, please reply to this message. We expect the day to be both fun and educational. Sincerely, Mr. Dawson','What must students return by May 2?',NULL,'["A list of parent volunteers","A completed science worksheet","A signed permission slip","Money for the bus ticket"]',2,'The permission slip is due by Friday, May 2.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-928f8e97f3c9','TOEFLJ','reading','mcq',3,'Dear Parents, On Thursday, May 8, our fifth-grade classes will visit the Riverside Science Museum. Buses will leave the school at 8:30 a.m. and return by 3:00 p.m. Students should wear comfortable shoes and bring a bag lunch, since the museum cafe is closed for repairs. Please do not pack glass bottles or foods with peanuts, because several students have serious allergies. Each student must return the signed permission slip by Friday, May 2; students without one will stay at school and join another class. Parent volunteers are still needed. If you can join us, please reply to this message. We expect the day to be both fun and educational. Sincerely, Mr. Dawson','Why does the teacher ask families not to pack foods with peanuts?',NULL,'["The museum bans all snacks.","Peanuts spoil quickly in warm weather.","Peanuts are messy on the bus.","Some students could become seriously ill from them."]',3,'Serious allergies are given as the reason.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-64b62a9ca7f8','TOEFLJ','reading','mcq',3,'Dear Parents, On Thursday, May 8, our fifth-grade classes will visit the Riverside Science Museum. Buses will leave the school at 8:30 a.m. and return by 3:00 p.m. Students should wear comfortable shoes and bring a bag lunch, since the museum cafe is closed for repairs. Please do not pack glass bottles or foods with peanuts, because several students have serious allergies. Each student must return the signed permission slip by Friday, May 2; students without one will stay at school and join another class. Parent volunteers are still needed. If you can join us, please reply to this message. We expect the day to be both fun and educational. Sincerely, Mr. Dawson','In the sentence "students without one will stay at school," the word "one" refers to',NULL,'["a permission slip","a museum ticket","a parent volunteer","a bus seat"]',0,'"One" stands for the signed permission slip mentioned just before.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-48ebf8a5765f','TOEFLJ','reading','mcq',2,'Mina stood on the porch, patting every pocket of her jacket. The key was gone. Her parents would not be home until six, and the wind was growing colder by the minute. She remembered kicking a soccer ball at the park after school, and she hurried back along the sidewalk, her eyes fixed on the ground. At the park, the grass was empty except for an old man feeding pigeons. "Did you see a key?" she asked. He smiled and pointed with his cane toward the bench. There, glinting in the afternoon sun, lay the key on a small silver ring. Mina laughed with relief and thanked him twice. As she walked home, she made a promise to herself: from now on, the key would stay zipped inside her backpack.','Why did Mina go back to the park?',NULL,'["The old man had called her name.","She wanted to feed the pigeons.","She remembered playing there earlier.","Her parents told her to look there."]',2,'She recalled kicking a soccer ball at the park.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a61bfd47672b','TOEFLJ','reading','mcq',2,'Mina stood on the porch, patting every pocket of her jacket. The key was gone. Her parents would not be home until six, and the wind was growing colder by the minute. She remembered kicking a soccer ball at the park after school, and she hurried back along the sidewalk, her eyes fixed on the ground. At the park, the grass was empty except for an old man feeding pigeons. "Did you see a key?" she asked. He smiled and pointed with his cane toward the bench. There, glinting in the afternoon sun, lay the key on a small silver ring. Mina laughed with relief and thanked him twice. As she walked home, she made a promise to herself: from now on, the key would stay zipped inside her backpack.','In the story, the word "glinting" most nearly means',NULL,'["hiding","shining","rusting","falling"]',1,'Something glinting in the sun is shining.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-b2b5517c807a','TOEFLJ','reading','mcq',3,'Mina stood on the porch, patting every pocket of her jacket. The key was gone. Her parents would not be home until six, and the wind was growing colder by the minute. She remembered kicking a soccer ball at the park after school, and she hurried back along the sidewalk, her eyes fixed on the ground. At the park, the grass was empty except for an old man feeding pigeons. "Did you see a key?" she asked. He smiled and pointed with his cane toward the bench. There, glinting in the afternoon sun, lay the key on a small silver ring. Mina laughed with relief and thanked him twice. As she walked home, she made a promise to herself: from now on, the key would stay zipped inside her backpack.','How did Mina feel at the end of the story?',NULL,'["Bored with her walk home","Relieved and determined to be more careful","Worried about the weather","Angry at the old man"]',1,'She laughed with relief and promised to keep the key safe.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-bdd6be5a3ff7','TOEFLJ','reading','mcq',3,'An octopus has no shell and no bones, yet it survives in waters full of hungry predators. Its best defense is camouflage. Special cells in its skin, called chromatophores, can expand or shrink in a fraction of a second. Each cell holds a tiny sac of color, so the octopus can turn from red to brown to nearly white as it moves across a reef. Some octopuses also change the texture of their skin, raising small bumps to look like rough rocks or seaweed. Scientists once believed the animal relied on its eyes to match its surroundings. However, recent studies suggest that the skin itself may sense light, helping the octopus blend in even when parts of its body are hidden from view. If camouflage fails, the octopus can squirt a cloud of dark ink and escape.','What is the main idea of the passage?',NULL,'["The octopus can only live near a reef.","The octopus builds shells from rocks.","The octopus is the fastest animal in the sea.","The octopus uses color and texture changes to protect itself."]',3,'Most of the passage describes how the octopus camouflages itself.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-10cba68bcdaa','TOEFLJ','reading','mcq',3,'An octopus has no shell and no bones, yet it survives in waters full of hungry predators. Its best defense is camouflage. Special cells in its skin, called chromatophores, can expand or shrink in a fraction of a second. Each cell holds a tiny sac of color, so the octopus can turn from red to brown to nearly white as it moves across a reef. Some octopuses also change the texture of their skin, raising small bumps to look like rough rocks or seaweed. Scientists once believed the animal relied on its eyes to match its surroundings. However, recent studies suggest that the skin itself may sense light, helping the octopus blend in even when parts of its body are hidden from view. If camouflage fails, the octopus can squirt a cloud of dark ink and escape.','What do chromatophores allow an octopus to do?',NULL,'["Change the color of its skin quickly","Grow new arms","Produce dark ink","See in complete darkness"]',0,'The passage says these skin cells expand or shrink to change color.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a4e172ce0c69','TOEFLJ','reading','mcq',4,'An octopus has no shell and no bones, yet it survives in waters full of hungry predators. Its best defense is camouflage. Special cells in its skin, called chromatophores, can expand or shrink in a fraction of a second. Each cell holds a tiny sac of color, so the octopus can turn from red to brown to nearly white as it moves across a reef. Some octopuses also change the texture of their skin, raising small bumps to look like rough rocks or seaweed. Scientists once believed the animal relied on its eyes to match its surroundings. However, recent studies suggest that the skin itself may sense light, helping the octopus blend in even when parts of its body are hidden from view. If camouflage fails, the octopus can squirt a cloud of dark ink and escape.','What do recent studies suggest?',NULL,'["Octopuses cannot see color at all.","Octopus skin may detect light on its own.","Octopus eyes are larger than scientists thought.","Octopuses only hide when they are hurt."]',1,'The passage says the skin itself may sense light.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-049c8279b2cd','TOEFLJ','reading','mcq',4,'An octopus has no shell and no bones, yet it survives in waters full of hungry predators. Its best defense is camouflage. Special cells in its skin, called chromatophores, can expand or shrink in a fraction of a second. Each cell holds a tiny sac of color, so the octopus can turn from red to brown to nearly white as it moves across a reef. Some octopuses also change the texture of their skin, raising small bumps to look like rough rocks or seaweed. Scientists once believed the animal relied on its eyes to match its surroundings. However, recent studies suggest that the skin itself may sense light, helping the octopus blend in even when parts of its body are hidden from view. If camouflage fails, the octopus can squirt a cloud of dark ink and escape.','In the passage, the phrase "blend in" most nearly means',NULL,'["swim in a group","move very fast","look like the surroundings","make a loud noise"]',2,'To blend in is to match what is around you.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-cf60a284babe','TOEFLJ','reading','mcq',4,'Beginning more than two thousand years ago, a network of trade routes known as the Silk Road linked China with the lands around the Mediterranean Sea. Few merchants traveled the entire distance. Instead, goods passed from trader to trader, and each handoff raised the price. Silk, spices, and paper moved westward, while glass, gold, and horses traveled east. Yet merchandise was not the only thing that crossed these deserts and mountains. Ideas, religions, and even diseases moved along the same paths. Buddhism, for instance, spread from India into East Asia largely through travelers on these roads. Towns along the way, such as Samarkand, grew wealthy by providing food, water, and shelter to caravans. Historians therefore describe the Silk Road not merely as a place for buying and selling but as a meeting point of cultures.','Why did goods become more expensive as they traveled along the Silk Road?',NULL,'["Merchants had to pay to cross the sea.","Governments banned silk from being sold.","Each trader who handled them raised the price.","Thieves destroyed most of the cargo."]',2,'The passage says each handoff raised the price.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-70db41265332','TOEFLJ','reading','mcq',4,'Beginning more than two thousand years ago, a network of trade routes known as the Silk Road linked China with the lands around the Mediterranean Sea. Few merchants traveled the entire distance. Instead, goods passed from trader to trader, and each handoff raised the price. Silk, spices, and paper moved westward, while glass, gold, and horses traveled east. Yet merchandise was not the only thing that crossed these deserts and mountains. Ideas, religions, and even diseases moved along the same paths. Buddhism, for instance, spread from India into East Asia largely through travelers on these roads. Towns along the way, such as Samarkand, grew wealthy by providing food, water, and shelter to caravans. Historians therefore describe the Silk Road not merely as a place for buying and selling but as a meeting point of cultures.','Why does the author mention Buddhism?',NULL,'["To describe the cities of China","To argue that religion caused wars","To explain why silk was so valuable","To show that ideas also traveled along the routes"]',3,'Buddhism is an example of ideas spreading with travelers.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-7d31e88f3462','TOEFLJ','reading','mcq',5,'Beginning more than two thousand years ago, a network of trade routes known as the Silk Road linked China with the lands around the Mediterranean Sea. Few merchants traveled the entire distance. Instead, goods passed from trader to trader, and each handoff raised the price. Silk, spices, and paper moved westward, while glass, gold, and horses traveled east. Yet merchandise was not the only thing that crossed these deserts and mountains. Ideas, religions, and even diseases moved along the same paths. Buddhism, for instance, spread from India into East Asia largely through travelers on these roads. Towns along the way, such as Samarkand, grew wealthy by providing food, water, and shelter to caravans. Historians therefore describe the Silk Road not merely as a place for buying and selling but as a meeting point of cultures.','The word "merchandise" in the passage most nearly means',NULL,'["roads for travel","goods for sale","stories from travelers","laws about trade"]',1,'Merchandise refers to items that are bought and sold.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-25ce401d25b5','TOEFLJ','reading','mcq',1,'Splash into summer at Maple Hill Swim Camp! Our camp runs for four weeks, from July 7 to August 1, Monday through Friday, 9:00 a.m. to noon. Beginners learn to float and kick in the shallow pool, while advanced swimmers practice racing turns with former college champions. Every group has no more than eight children, so each swimmer gets plenty of attention. The fee is $180 per week, but families who sign up for all four weeks before June 1 pay only $600 in total. Sunscreen and towels are not provided, so please bring your own. Call 555-0142 today, because spaces fill quickly.','What should campers bring with them?',NULL,'["A signed doctor''s note","Racing goggles and a cap","Sunscreen and towels","Lunch and a water bottle"]',2,'The ad says sunscreen and towels are not provided.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-f16aca9918d4','TOEFLJ','reading','mcq',2,'Splash into summer at Maple Hill Swim Camp! Our camp runs for four weeks, from July 7 to August 1, Monday through Friday, 9:00 a.m. to noon. Beginners learn to float and kick in the shallow pool, while advanced swimmers practice racing turns with former college champions. Every group has no more than eight children, so each swimmer gets plenty of attention. The fee is $180 per week, but families who sign up for all four weeks before June 1 pay only $600 in total. Sunscreen and towels are not provided, so please bring your own. Call 555-0142 today, because spaces fill quickly.','How much money does a family save by signing up for all four weeks before June 1?',NULL,'["$600","$120","$60","$180"]',1,'Four weeks at $180 cost $720; $720 minus $600 is $120.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-e784b2a6c1b7','TOEFLJ','reading','mcq',2,'Splash into summer at Maple Hill Swim Camp! Our camp runs for four weeks, from July 7 to August 1, Monday through Friday, 9:00 a.m. to noon. Beginners learn to float and kick in the shallow pool, while advanced swimmers practice racing turns with former college champions. Every group has no more than eight children, so each swimmer gets plenty of attention. The fee is $180 per week, but families who sign up for all four weeks before June 1 pay only $600 in total. Sunscreen and towels are not provided, so please bring your own. Call 555-0142 today, because spaces fill quickly.','Why does the ad say "Call 555-0142 today"?',NULL,'["Spaces in the camp fill up quickly.","The fee will double tomorrow.","The camp is already closed.","Only advanced swimmers may enroll."]',0,'The ad explains that spaces fill quickly, encouraging fast action.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-8c0ac23b383f','TOEFLJ','reading','mcq',3,'Dear Families, Beginning next month, Harbor Middle School will move to a split lunch schedule. At present, all 600 students eat together at 12:15, which creates long lines and leaves many students with only ten minutes to finish their meals. Under the new plan, sixth and seventh graders will eat at 11:45, and eighth graders will eat at 12:30. The change will not shorten any class, but some periods will begin five minutes later. Teachers have already adjusted their lesson plans. We understand that some students will miss eating with friends in other grades. To address this concern, the cafeteria will host a monthly Friday lunch when all grades may sit together. We believe the new system will make lunchtime calmer and give everyone enough time to eat. Please contact the office with questions. Sincerely, Principal Okafor','Why is the school changing its lunch schedule?',NULL,'["Long lines leave students too little time to eat.","Teachers want longer classes.","The cafeteria will be closed for repairs.","Fewer students are buying lunch."]',0,'The letter cites long lines and only ten minutes to eat.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-4570896b70cb','TOEFLJ','reading','mcq',3,'Dear Families, Beginning next month, Harbor Middle School will move to a split lunch schedule. At present, all 600 students eat together at 12:15, which creates long lines and leaves many students with only ten minutes to finish their meals. Under the new plan, sixth and seventh graders will eat at 11:45, and eighth graders will eat at 12:30. The change will not shorten any class, but some periods will begin five minutes later. Teachers have already adjusted their lesson plans. We understand that some students will miss eating with friends in other grades. To address this concern, the cafeteria will host a monthly Friday lunch when all grades may sit together. We believe the new system will make lunchtime calmer and give everyone enough time to eat. Please contact the office with questions. Sincerely, Principal Okafor','Which students will eat at 12:30?',NULL,'["Sixth graders","All students","Seventh graders","Eighth graders"]',3,'The letter says eighth graders will eat at 12:30.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-fd747444f345','TOEFLJ','reading','mcq',4,'Dear Families, Beginning next month, Harbor Middle School will move to a split lunch schedule. At present, all 600 students eat together at 12:15, which creates long lines and leaves many students with only ten minutes to finish their meals. Under the new plan, sixth and seventh graders will eat at 11:45, and eighth graders will eat at 12:30. The change will not shorten any class, but some periods will begin five minutes later. Teachers have already adjusted their lesson plans. We understand that some students will miss eating with friends in other grades. To address this concern, the cafeteria will host a monthly Friday lunch when all grades may sit together. We believe the new system will make lunchtime calmer and give everyone enough time to eat. Please contact the office with questions. Sincerely, Principal Okafor','Why will the cafeteria hold a monthly Friday lunch for all grades?',NULL,'["To help students who will miss friends in other grades","To practice a fire drill","To give teachers a longer break","To save money on food"]',0,'The monthly lunch is offered to address the concern about missing friends.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-30373a08aea4','TOEFLJ','reading','mcq',4,'Dear Families, Beginning next month, Harbor Middle School will move to a split lunch schedule. At present, all 600 students eat together at 12:15, which creates long lines and leaves many students with only ten minutes to finish their meals. Under the new plan, sixth and seventh graders will eat at 11:45, and eighth graders will eat at 12:30. The change will not shorten any class, but some periods will begin five minutes later. Teachers have already adjusted their lesson plans. We understand that some students will miss eating with friends in other grades. To address this concern, the cafeteria will host a monthly Friday lunch when all grades may sit together. We believe the new system will make lunchtime calmer and give everyone enough time to eat. Please contact the office with questions. Sincerely, Principal Okafor','In the letter, the word "address" most nearly means',NULL,'["write to","hide from","look at","deal with"]',3,'To address a concern is to respond to it.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-8f5b4e839444','TOEFLJ','reading','mcq',3,'Every spring, Grandfather Chen knelt in the same corner of the yard and pressed a handful of seeds into the soil as gently as if he were tucking in a baby. Lian, who was nine, thought it was a strange habit, since the store sold tomatoes all year. "Those are not the same tomatoes," he told her one morning, wiping his hands on his old gray apron. "These seeds came from my mother''s garden in Hangzhou. She gave them to me the day I left." Lian looked at the tiny brown specks with new respect. That summer, she watered the plants every evening without being asked, and when the first tomato turned red, she carried it to her grandfather in both hands. He did not say anything at first; he only held it up to the light, and his eyes shone.','Why does Grandfather Chen plant these seeds every spring?',NULL,'["They connect him to his mother and his old home.","He wants to sell tomatoes at the market.","They grow faster than store seeds.","Lian asked him to start a garden."]',0,'The seeds came from his mother''s garden in Hangzhou.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-040f6252ff8a','TOEFLJ','reading','mcq',3,'Every spring, Grandfather Chen knelt in the same corner of the yard and pressed a handful of seeds into the soil as gently as if he were tucking in a baby. Lian, who was nine, thought it was a strange habit, since the store sold tomatoes all year. "Those are not the same tomatoes," he told her one morning, wiping his hands on his old gray apron. "These seeds came from my mother''s garden in Hangzhou. She gave them to me the day I left." Lian looked at the tiny brown specks with new respect. That summer, she watered the plants every evening without being asked, and when the first tomato turned red, she carried it to her grandfather in both hands. He did not say anything at first; he only held it up to the light, and his eyes shone.','What does the phrase "new respect" show about Lian?',NULL,'["She wanted to buy better seeds.","She was afraid of the garden.","She now understood why the seeds mattered.","She thought the work was too hard."]',2,'After hearing the story, she treated the seeds as important.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a85ca46f79ad','TOEFLJ','reading','mcq',4,'Every spring, Grandfather Chen knelt in the same corner of the yard and pressed a handful of seeds into the soil as gently as if he were tucking in a baby. Lian, who was nine, thought it was a strange habit, since the store sold tomatoes all year. "Those are not the same tomatoes," he told her one morning, wiping his hands on his old gray apron. "These seeds came from my mother''s garden in Hangzhou. She gave them to me the day I left." Lian looked at the tiny brown specks with new respect. That summer, she watered the plants every evening without being asked, and when the first tomato turned red, she carried it to her grandfather in both hands. He did not say anything at first; he only held it up to the light, and his eyes shone.','Why did Grandfather Chen stay silent when Lian gave him the tomato?',NULL,'["He was deeply moved.","He was angry about the mess.","He had forgotten her name.","He did not like tomatoes."]',0,'His shining eyes suggest strong emotion rather than anger or indifference.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-b8cd0533e0e0','TOEFLJ','reading','mcq',4,'Every spring, Grandfather Chen knelt in the same corner of the yard and pressed a handful of seeds into the soil as gently as if he were tucking in a baby. Lian, who was nine, thought it was a strange habit, since the store sold tomatoes all year. "Those are not the same tomatoes," he told her one morning, wiping his hands on his old gray apron. "These seeds came from my mother''s garden in Hangzhou. She gave them to me the day I left." Lian looked at the tiny brown specks with new respect. That summer, she watered the plants every evening without being asked, and when the first tomato turned red, she carried it to her grandfather in both hands. He did not say anything at first; he only held it up to the light, and his eyes shone.','In the story, the word "habit" most nearly means',NULL,'["a mistake made once","something a person does regularly","a gift from a friend","a kind of clothing"]',1,'A habit is a regular practice.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-1be2a290385f','TOEFLJ','reading','mcq',4,'When a honeybee finds a rich patch of flowers, she returns to the hive and performs a figure-eight dance on the honeycomb. The straight middle part of the dance, called the waggle run, carries the message. The angle of the run, measured against gravity, tells the other bees which direction to fly relative to the sun. The length of the run indicates distance: the longer the waggle, the farther the flowers. Researchers who first decoded the dance in the 1940s were astonished, because it suggested that insects could share precise information symbolically. Later experiments strengthened that view. When scientists moved a food source while a hive''s dancers were advertising its old location, bees that followed the dance arrived at the empty spot and searched there, which showed that they were relying on the dancers'' directions rather than simply smelling the food.','What does the length of the waggle run tell other bees?',NULL,'["Which flower is the largest","How many bees should go","How sweet the nectar is","How far away the flowers are"]',3,'The passage says a longer waggle means farther flowers.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a1b151652f6a','TOEFLJ','reading','mcq',5,'When a honeybee finds a rich patch of flowers, she returns to the hive and performs a figure-eight dance on the honeycomb. The straight middle part of the dance, called the waggle run, carries the message. The angle of the run, measured against gravity, tells the other bees which direction to fly relative to the sun. The length of the run indicates distance: the longer the waggle, the farther the flowers. Researchers who first decoded the dance in the 1940s were astonished, because it suggested that insects could share precise information symbolically. Later experiments strengthened that view. When scientists moved a food source while a hive''s dancers were advertising its old location, bees that followed the dance arrived at the empty spot and searched there, which showed that they were relying on the dancers'' directions rather than simply smelling the food.','Why were the researchers astonished?',NULL,'["The dance showed insects could share exact information.","Bees could not find flowers alone.","The dance was the same for every bee.","Bees danced only at night."]',0,'The passage says the dance suggested insects share precise information symbolically.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-80f1ba661d0c','TOEFLJ','reading','mcq',5,'When a honeybee finds a rich patch of flowers, she returns to the hive and performs a figure-eight dance on the honeycomb. The straight middle part of the dance, called the waggle run, carries the message. The angle of the run, measured against gravity, tells the other bees which direction to fly relative to the sun. The length of the run indicates distance: the longer the waggle, the farther the flowers. Researchers who first decoded the dance in the 1940s were astonished, because it suggested that insects could share precise information symbolically. Later experiments strengthened that view. When scientists moved a food source while a hive''s dancers were advertising its old location, bees that followed the dance arrived at the empty spot and searched there, which showed that they were relying on the dancers'' directions rather than simply smelling the food.','What did the experiment with the moved food source demonstrate?',NULL,'["Scientists can teach bees new dances.","Bees ignore food that is far away.","Bees followed the dance directions instead of using smell.","Bees dance only near the hive entrance."]',2,'Bees flew to the empty old location, so they relied on the directions.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-c53b224b8d32','TOEFLJ','reading','mcq',3,'Before canals, farmers in inland regions often struggled to sell their crops. Wagons were slow, roads turned to mud in the rain, and a heavy load of grain could cost nearly as much to haul as it was worth. Then a canal was dug linking the interior to the coast. Barges pulled by mules carried goods for a fraction of the price, and shipping times dropped from weeks to days. Towns along the waterway grew into busy markets, and farmers began planting crops specifically to sell rather than only to feed their families. Within a generation, however, railroads arrived and were faster still. Many canals fell out of use, and some towns that had boomed began to shrink.','Why did farmers have trouble selling crops before the canal?',NULL,'["Moving crops by wagon was slow and costly.","Farmers had no land to plant on.","Few people wanted to buy grain.","The coast had no markets."]',0,'Wagons were slow and hauling could cost almost as much as the crop was worth.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-e1d112447cd5','TOEFLJ','reading','mcq',3,'Before canals, farmers in inland regions often struggled to sell their crops. Wagons were slow, roads turned to mud in the rain, and a heavy load of grain could cost nearly as much to haul as it was worth. Then a canal was dug linking the interior to the coast. Barges pulled by mules carried goods for a fraction of the price, and shipping times dropped from weeks to days. Towns along the waterway grew into busy markets, and farmers began planting crops specifically to sell rather than only to feed their families. Within a generation, however, railroads arrived and were faster still. Many canals fell out of use, and some towns that had boomed began to shrink.','How did the canal change farming?',NULL,'["Farmers moved to the coast.","Farmers stopped planting grain.","Farmers began using mules for the first time.","Farmers grew crops mainly to sell."]',3,'Farmers began planting crops specifically to sell.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-aaccc1ca4e65','TOEFLJ','reading','mcq',4,'Before canals, farmers in inland regions often struggled to sell their crops. Wagons were slow, roads turned to mud in the rain, and a heavy load of grain could cost nearly as much to haul as it was worth. Then a canal was dug linking the interior to the coast. Barges pulled by mules carried goods for a fraction of the price, and shipping times dropped from weeks to days. Towns along the waterway grew into busy markets, and farmers began planting crops specifically to sell rather than only to feed their families. Within a generation, however, railroads arrived and were faster still. Many canals fell out of use, and some towns that had boomed began to shrink.','In the passage, "a fraction of the price" means',NULL,'["twice the old price","exactly the same price","a price nobody could pay","much less than the old price"]',3,'A fraction of the price is only a small part of it.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-900bb27a99d7','TOEFLJ','reading','mcq',5,'Before canals, farmers in inland regions often struggled to sell their crops. Wagons were slow, roads turned to mud in the rain, and a heavy load of grain could cost nearly as much to haul as it was worth. Then a canal was dug linking the interior to the coast. Barges pulled by mules carried goods for a fraction of the price, and shipping times dropped from weeks to days. Towns along the waterway grew into busy markets, and farmers began planting crops specifically to sell rather than only to feed their families. Within a generation, however, railroads arrived and were faster still. Many canals fell out of use, and some towns that had boomed began to shrink.','What can be inferred about towns that shrank after railroads arrived?',NULL,'["They had been built by the railroad.","Their farmers stopped growing food.","They had depended on canal traffic for business.","They were located far from any water."]',2,'As canals lost traffic to faster trains, canal-side towns lost business.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-a61561608cfc','TOEFLJ','reading','mcq',2,'The Lakeside Youth Theater will present its spring play, The Lost Lantern, on three days. Opening night is Friday, June 6, at 7:00 p.m. A second performance follows on Saturday, June 7, also at 7:00, and a matinee at 2:00 p.m. on Sunday, June 8, is designed for younger children and runs only 45 minutes. Tickets cost $8 for students and $12 for adults, but children under five enter free. Seating is first come, first served, so doors open thirty minutes before each show. Parents of cast members may bring cookies to the lobby table on Saturday.','At what time do the doors open on Friday?',NULL,'["2:00 p.m.","6:30 p.m.","7:00 p.m.","6:00 p.m."]',1,'Doors open thirty minutes before the 7:00 p.m. show.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-0e22b57e3696','TOEFLJ','reading','mcq',3,'The Lakeside Youth Theater will present its spring play, The Lost Lantern, on three days. Opening night is Friday, June 6, at 7:00 p.m. A second performance follows on Saturday, June 7, also at 7:00, and a matinee at 2:00 p.m. on Sunday, June 8, is designed for younger children and runs only 45 minutes. Tickets cost $8 for students and $12 for adults, but children under five enter free. Seating is first come, first served, so doors open thirty minutes before each show. Parents of cast members may bring cookies to the lobby table on Saturday.','How much would two adults and one student pay for tickets?',NULL,'["$28","$36","$32","$44"]',2,'Two adults cost $24 and one student costs $8, so the total is $32.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-7236360380b6','TOEFLJ','reading','mcq',3,'The Lakeside Youth Theater will present its spring play, The Lost Lantern, on three days. Opening night is Friday, June 6, at 7:00 p.m. A second performance follows on Saturday, June 7, also at 7:00, and a matinee at 2:00 p.m. on Sunday, June 8, is designed for younger children and runs only 45 minutes. Tickets cost $8 for students and $12 for adults, but children under five enter free. Seating is first come, first served, so doors open thirty minutes before each show. Parents of cast members may bring cookies to the lobby table on Saturday.','Why might a family arrive early for a show?',NULL,'["Seats are not assigned in advance.","The play starts when the doors open.","Cookies are served before each show.","Tickets are free for early guests."]',0,'With first-come seating, early arrivals choose better seats.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-b90dc9d88a3e','TOEFLJ','reading','mcq',4,'Leaves look green in summer because they contain chlorophyll, a pigment that captures sunlight for making food. As days grow shorter in autumn, trees stop producing chlorophyll, and the green fades. The yellow and orange colors that remain were present all along; they were simply hidden. Red leaves are different. Their color comes from anthocyanins, pigments that many trees manufacture only in autumn, from sugars trapped in the leaves. Bright, sunny days and cool nights produce the richest reds, because sunshine builds up sugar while cold prevents it from leaving the leaf. In a cloudy, warm autumn, the display is usually duller. Brown leaves, finally, result from waste products left behind after the other pigments are gone.','Why do yellow and orange colors appear in autumn?',NULL,'["They show once the green chlorophyll fades.","Trees make them from sunlight in October.","Cold air changes green leaves to yellow.","They are produced from trapped sugars."]',0,'Those colors were present all along but hidden by chlorophyll.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-965d6916f439','TOEFLJ','reading','mcq',4,'Leaves look green in summer because they contain chlorophyll, a pigment that captures sunlight for making food. As days grow shorter in autumn, trees stop producing chlorophyll, and the green fades. The yellow and orange colors that remain were present all along; they were simply hidden. Red leaves are different. Their color comes from anthocyanins, pigments that many trees manufacture only in autumn, from sugars trapped in the leaves. Bright, sunny days and cool nights produce the richest reds, because sunshine builds up sugar while cold prevents it from leaving the leaf. In a cloudy, warm autumn, the display is usually duller. Brown leaves, finally, result from waste products left behind after the other pigments are gone.','How are red leaves different from yellow ones?',NULL,'["They come from waste products.","They stay on the tree longer.","They contain more chlorophyll.","Their pigment is newly made in autumn."]',3,'Anthocyanins are manufactured only in autumn, unlike the hidden yellow pigments.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-33f9d80dc342','TOEFLJ','reading','mcq',5,'Leaves look green in summer because they contain chlorophyll, a pigment that captures sunlight for making food. As days grow shorter in autumn, trees stop producing chlorophyll, and the green fades. The yellow and orange colors that remain were present all along; they were simply hidden. Red leaves are different. Their color comes from anthocyanins, pigments that many trees manufacture only in autumn, from sugars trapped in the leaves. Bright, sunny days and cool nights produce the richest reds, because sunshine builds up sugar while cold prevents it from leaving the leaf. In a cloudy, warm autumn, the display is usually duller. Brown leaves, finally, result from waste products left behind after the other pigments are gone.','Which weather would most likely produce the brightest red leaves?',NULL,'["Sunny days and cool nights","Foggy days and freezing nights","Cloudy days and warm nights","Rainy days and warm nights"]',0,'The passage says sunny days and cool nights produce the richest reds.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-toeflj-reading-e10779cd257a','TOEFLJ','reading','mcq',5,'Leaves look green in summer because they contain chlorophyll, a pigment that captures sunlight for making food. As days grow shorter in autumn, trees stop producing chlorophyll, and the green fades. The yellow and orange colors that remain were present all along; they were simply hidden. Red leaves are different. Their color comes from anthocyanins, pigments that many trees manufacture only in autumn, from sugars trapped in the leaves. Bright, sunny days and cool nights produce the richest reds, because sunshine builds up sugar while cold prevents it from leaving the leaf. In a cloudy, warm autumn, the display is usually duller. Brown leaves, finally, result from waste products left behind after the other pigments are gone.','In the passage, "display" most nearly means',NULL,'["a type of weather","a showing of colors","a warning sign","a kind of tree"]',1,'The autumn display is the visible show of leaf colors.',1,0);
