INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-51d1444c09d3','SAT','math','mcq',2,NULL,'A rectangular poster is 10 inches wide and 5 inches tall. A rectangular 7-inch by 2-inch photo is placed on it. What is the area, in square inches, of the part of the poster NOT covered by the photo?',NULL,'["64","14","36","50"]',2,'10 × 5 − 7 × 2 = 36.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-ded2622b9ab3','SAT','math','mcq',3,NULL,'A theater sold adult tickets for $15 each and child tickets for $11 each. In all, 34 tickets were sold for $446. How many adult tickets were sold?',NULL,'["16","19","17","18"]',3,'Let x be the adult tickets: x + y = 34 and 15x + 11y = 446. Solving gives x = 18.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-82033bae6cd6','SAT','math','mcq',2,NULL,'What is the median of the data set 6, 16, 8, 9, 13, 11, 17?',NULL,'["9","11","12","13"]',1,'Order the values: 6, 8, 9, 11, 13, 16, 17. The middle (4th) value is 11.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-bc40209b4750','SAT','math','mcq',3,NULL,'A colony starts with 20 bacteria and doubles every 4 hours. How many bacteria are there after 16 hours?',NULL,'["320","160","640","28"]',0,'4 doublings: 20 × 2^4.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-281fb83f4301','SAT','math','mcq',4,NULL,'The function f(x) = −(x + 3)² + 3 is graphed in the xy-plane. What is the maximum value of f?',NULL,'["-3","3","9","6"]',1,'The squared term is never positive, so the maximum value is the constant 3.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-b40b7dc69af0','SAT','math','mcq',3,NULL,'Triangle ABC is similar to triangle DEF, with AB = 5, DE = 15, and BC = 3. What is the length of EF?',NULL,'["14","13","6","9"]',3,'The scale factor is DE/AB = 3, so EF = 3 × 3.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-aa664aaad6ce','SAT','math','mcq',3,NULL,'The equation y = 18x + 26 models the height, in centimeters, of a plant x weeks after planting. What does the number 18 represent in this context?',NULL,'["the plant''s growth in height each week","the number of weeks since planting","the plant''s height when it was planted","the plant''s height after one week"]',0,'In y = mx + b, m is the rate of change of y for each 1-unit increase in x.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-59bd226fa21e','SAT','math','mcq',2,NULL,'10% of a number is 75. What is the number?',NULL,'["760","150","750","675"]',2,'75 ÷ 0.1 = 750.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-f61aa8bcd8e8','SAT','math','mcq',2,NULL,'A train travels at a constant speed of 54 kilometers per hour. How many kilometers does it travel in 20 minutes?',NULL,'["18","3","1080","10.8"]',0,'20 minutes = 20/60 hour, so the distance is 54 × 20/60 = 18.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-4a429dce93c8','SAT','math','mcq',3,NULL,'Dana has $80. She pays a $5 entry fee and then buys snacks that cost $8 each. What is the greatest number of snacks she can buy?',NULL,'["10","8","9","11"]',2,'8n + 5 ≤ 80, so n ≤ 9.38; the greatest whole number is 9.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-0aab220d36e5','SAT','math','mcq',2,NULL,'A spinner has 12 equal sections, 3 of which are red. What is the probability that a spin does NOT land on red?',NULL,'["9/3","1/4","3/4","10/12"]',2,'9 of the 12 sections are not red.',1,0);
