INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-287770147402','SAT','math','mcq',2,NULL,'A rectangular poster is 13 inches wide and 10 inches tall. A rectangular 6-inch by 7-inch photo is placed on it. What is the area, in square inches, of the part of the poster NOT covered by the photo?',NULL,'["130","172","88","42"]',2,'13 × 10 − 6 × 7 = 88.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-f6ace284a9f1','SAT','math','mcq',3,NULL,'A theater sold adult tickets for $13 each and child tickets for $11 each. In all, 22 tickets were sold for $264. How many adult tickets were sold?',NULL,'["11","22","12","10"]',0,'Let x be the adult tickets: x + y = 22 and 13x + 11y = 264. Solving gives x = 11.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-d94dc517c999','SAT','math','mcq',2,NULL,'What is the median of the data set 18, 7, 12, 9, 14, 10, 17?',NULL,'["12","13","14","10"]',0,'Order the values: 7, 9, 10, 12, 14, 17, 18. The middle (4th) value is 12.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-9c32e0d3a198','SAT','math','mcq',3,NULL,'A colony starts with 200 bacteria and doubles every 2 hours. How many bacteria are there after 4 hours?',NULL,'["1600","800","204"]',1,'2 doublings: 200 × 2^2.',1,0);
