INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-c218dfbd49ae','SAT','math','mcq',3,NULL,'Triangle ABC is similar to triangle DEF, with AB = 4, DE = 8, and BC = 6. What is the length of EF?',NULL,'["16","12","8","10"]',1,'The scale factor is DE/AB = 2, so EF = 6 × 2.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-1031b9949ec7','SAT','math','mcq',3,NULL,'The equation y = 24x + 43 models the cost, in dollars, of renting a bike for x hours. What does the number 24 represent in this context?',NULL,'["the total cost for one hour","the fixed fee charged regardless of hours","the cost for each additional hour","the number of hours rented"]',2,'In y = mx + b, m is the rate of change of y for each 1-unit increase in x.',1,0);
