INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-ge24e614ae62a','SAT','math','num',4,NULL,'A recipe uses 6 cups of oats for every 8 cups of flour. How many cups of oats are used for each cup of flour? (Answer as a fraction or decimal.)  (Enter your answer.)',NULL,'["3/4"]',NULL,'6 ÷ 8 = 3/4 = 0.75.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-gbf1c201067b1','SAT','math','num',2,NULL,'If 2x − 8 = 32, what is the value of x?  (Enter your answer.)',NULL,'["20"]',NULL,'Add 8 to both sides and divide by 2.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-g795cf8255bb9','SAT','math','num',4,NULL,'The function g is defined by g(x) = 5x² − x + 5. What is the value of g(4)?  (Enter your answer.)',NULL,'["81"]',NULL,'5(4)² − 1(4) + 5 = 81.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-gf2e74c141283','SAT','math','num',2,NULL,'What is 15% of 80?  (Enter your answer.)',NULL,'["12"]',NULL,'15/100 × 80 = 12.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-g687b8a2b65b5','SAT','math','num',3,NULL,'The mean of five numbers is 22. Four of the numbers are 40, 26, 10, 13. What is the fifth number?  (Enter your answer.)',NULL,'["21"]',NULL,'The total is 5 × 22 = 110; subtract the four known numbers.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-ge71769743514','SAT','math','num',3,NULL,'A triangle has a base of 12 centimeters and a height of 10 centimeters. What is its area, in square centimeters?  (Enter your answer.)',NULL,'["60"]',NULL,'Area = ½ × 12 × 10.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-gad2e8eb63203','SAT','math','num',3,NULL,'If 2x + y = 12 and x − y = 0, what is the value of y?  (Enter your answer.)',NULL,'["4"]',NULL,'Adding the equations gives 3x = 12, so x = 4 and y = 4.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-sat-math-g981be8dd7ce8','SAT','math','num',3,NULL,'A cyclist rides at a constant 60 kilometers per hour for 2.5 hours. How many kilometers does she ride?  (Enter your answer.)',NULL,'["150"]',NULL,'60 × 2.5 = 150.',1,0);
